INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'creation', 'talents', 'Talents de Réalité : place et mécanique', NULL, '{"nature":"creation","origin":{"corporatiste":[{"id":"codes_corporatifs","category":"origin","origin":"corporatiste"},{"id":"formation_calibree","category":"origin","origin":"corporatiste"},{"id":"culture_produit","category":"origin","origin":"corporatiste"},{"id":"reseau_scolaire","category":"origin","origin":"corporatiste"},{"id":"toujours_presentable","category":"origin","origin":"corporatiste"}],"gouvernementale":[{"id":"education_civique","category":"origin","origin":"gouvernementale"},{"id":"procedures_administratives","category":"origin","origin":"gouvernementale"},{"id":"famille_de_fonctionnaires","category":"origin","origin":"gouvernementale"},{"id":"formation_publique","category":"origin","origin":"gouvernementale"},{"id":"dossier_propre","category":"origin","origin":"gouvernementale"}],"mafieuse":[{"id":"codes_du_milieu","category":"origin","origin":"mafieuse"},{"id":"omerta_familiale","category":"origin","origin":"mafieuse"},{"id":"enfant_du_quartier","category":"origin","origin":"mafieuse"},{"id":"vieilles_frequentations","category":"origin","origin":"mafieuse"},{"id":"petites_combines","category":"origin","origin":"mafieuse"}],"religieuse":[{"id":"education_doctrinale","category":"origin","origin":"religieuse"},{"id":"vie_communautaire","category":"origin","origin":"religieuse"},{"id":"discipline_de_foi","category":"origin","origin":"religieuse"},{"id":"communaute_dorigine","category":"origin","origin":"religieuse"},{"id":"education_caritative","category":"origin","origin":"religieuse"}],"crawler":[{"id":"debrouille","category":"origin","origin":"crawler"},{"id":"codes_de_rue","category":"origin","origin":"crawler"},{"id":"enfant_des_zones_mortes","category":"origin","origin":"crawler"},{"id":"on_connait_quelquun","category":"origin","origin":"crawler"},{"id":"recuperateur","category":"origin","origin":"crawler"}]},"sphere":{"corporatiste":[{"id":"dotation_standard","category":"sphere","sphere":"corporatiste"},{"id":"assurance_corporative","category":"sphere","sphere":"corporatiste"},{"id":"badge_interne","category":"sphere","sphere":"corporatiste"},{"id":"avantages_salaries","category":"sphere","sphere":"corporatiste"},{"id":"compte_de_frais","category":"sphere","sphere":"corporatiste"},{"id":"reseau_interne","category":"sphere","sphere":"corporatiste"},{"id":"profil_calibre","category":"sphere","sphere":"corporatiste"},{"id":"acces_fournisseur","category":"sphere","sphere":"corporatiste"},{"id":"service_juridique","category":"sphere","sphere":"corporatiste"},{"id":"programme_pilote","category":"sphere","sphere":"corporatiste"},{"id":"extraction_corporative","category":"sphere","sphere":"corporatiste"},{"id":"requin_corporatif","category":"sphere","sphere":"corporatiste"}],"gouvernementale":[{"id":"dotation_de_service","category":"sphere","sphere":"gouvernementale"},{"id":"habilitation_administrative","category":"sphere","sphere":"gouvernementale"},{"id":"reseau_administratif","category":"sphere","sphere":"gouvernementale"},{"id":"acces_aux_registres","category":"sphere","sphere":"gouvernementale"},{"id":"procedure_acceleree","category":"sphere","sphere":"gouvernementale"},{"id":"fonctionnaire_experimente","category":"sphere","sphere":"gouvernementale"},{"id":"requisition_de_service","category":"sphere","sphere":"gouvernementale"},{"id":"couverture_fonctionnelle","category":"sphere","sphere":"gouvernementale"},{"id":"dossier_institutionnel","category":"sphere","sphere":"gouvernementale"},{"id":"autorite_officielle","category":"sphere","sphere":"gouvernementale"},{"id":"priorite_interservices","category":"sphere","sphere":"gouvernementale"},{"id":"appui_du_service","category":"sphere","sphere":"gouvernementale"}],"mafieuse":[{"id":"protection","category":"sphere","sphere":"mafieuse"},{"id":"marche_noir","category":"sphere","sphere":"mafieuse"},{"id":"receleur","category":"sphere","sphere":"mafieuse"},{"id":"blanchiment","category":"sphere","sphere":"mafieuse"},{"id":"faussaires","category":"sphere","sphere":"mafieuse"},{"id":"dette_de_faveur","category":"sphere","sphere":"mafieuse"},{"id":"omerta","category":"sphere","sphere":"mafieuse"},{"id":"planque","category":"sphere","sphere":"mafieuse"},{"id":"homme_femme_du_milieu","category":"sphere","sphere":"mafieuse"},{"id":"armurier_du_milieu","category":"sphere","sphere":"mafieuse"},{"id":"entreprise_de_couverture","category":"sphere","sphere":"mafieuse"},{"id":"corruption_locale","category":"sphere","sphere":"mafieuse"}],"crawler":[{"id":"fiable","category":"sphere","sphere":"crawler"},{"id":"bonnes_adresses","category":"sphere","sphere":"crawler"},{"id":"dans_le_coup","category":"sphere","sphere":"crawler"},{"id":"contact_de_renom","category":"sphere","sphere":"crawler"},{"id":"assurance_silver","category":"sphere","sphere":"crawler"},{"id":"maitrise_des_codes_de_la_rue","category":"sphere","sphere":"crawler"},{"id":"optitech","category":"sphere","sphere":"crawler"},{"id":"logifake","category":"sphere","sphere":"crawler"},{"id":"nid_de_frelons","category":"sphere","sphere":"crawler"},{"id":"insignifiant","category":"sphere","sphere":"crawler"},{"id":"fixweb","category":"sphere","sphere":"crawler"},{"id":"black_clinic","category":"sphere","sphere":"crawler"}],"religieuse":[{"id":"communaute_de_fideles","category":"sphere","sphere":"religieuse"},{"id":"autorite_religieuse","category":"sphere","sphere":"religieuse"},{"id":"ministere","category":"sphere","sphere":"religieuse"},{"id":"mission_ecclesiastique","category":"sphere","sphere":"religieuse"},{"id":"hebergement_religieux","category":"sphere","sphere":"religieuse"},{"id":"reseau_caritatif","category":"sphere","sphere":"religieuse"},{"id":"education_theologique","category":"sphere","sphere":"religieuse"},{"id":"conseiller_spirituel","category":"sphere","sphere":"religieuse"},{"id":"presence_holonet","category":"sphere","sphere":"religieuse"},{"id":"soutien_communautaire","category":"sphere","sphere":"religieuse"},{"id":"ordre_religieux","category":"sphere","sphere":"religieuse"},{"id":"reseau_confessionnel","category":"sphere","sphere":"religieuse"}]},"common":[{"id":"sommeil_leger","category":"common"},{"id":"resistance_a_la_chaleur","category":"common"},{"id":"resistance_au_froid","category":"common"},{"id":"sante_de_fer","category":"common"},{"id":"insensibilite_a_la_douleur","category":"common"},{"id":"nageur","category":"common"},{"id":"ambidextre","category":"common"},{"id":"brave","category":"common"},{"id":"fier_heritier","category":"common"},{"id":"renomme","category":"common"},{"id":"presence_remarquable","category":"common"},{"id":"apprentissage_fulgurant","category":"common"}],"expertise":[{"id":"athlete","category":"expertise","attribute":"vigueur","skill":"athletisme","prerequisite":null},{"id":"poings_de_fer","category":"expertise","attribute":"vigueur","skill":"pugilat","prerequisite":null},{"id":"stabilite_augmentique","category":"expertise","attribute":"vigueur","skill":"humanite","prerequisite":null},{"id":"maitre_des_lames","category":"expertise","attribute":"vigueur","skill":"melee","prerequisite":null},{"id":"resistance_aux_toxines","category":"expertise","attribute":"vigueur","skill":"constitution","prerequisite":null},{"id":"tireur_de_precision","category":"expertise","attribute":"agilite","skill":"tir","prerequisite":null},{"id":"pilote_emerite","category":"expertise","attribute":"agilite","skill":"pilotage","prerequisite":null},{"id":"ombre_vivante","category":"expertise","attribute":"agilite","skill":"furtivite","prerequisite":null},{"id":"reflexes_defensifs","category":"expertise","attribute":"agilite","skill":"esquive","prerequisite":null},{"id":"mains_lestes","category":"expertise","attribute":"agilite","skill":"larcin","prerequisite":null},{"id":"linguiste_emerite","category":"expertise","attribute":"esprit","skill":"langages_argot","prerequisite":null},{"id":"puits_de_savoir","category":"expertise","attribute":"esprit","skill":"savoirs","prerequisite":null},{"id":"doc_de_choc","category":"expertise","attribute":"esprit","skill":"soin","prerequisite":null},{"id":"mecano_de_pointe","category":"expertise","attribute":"esprit","skill":"mecanique","prerequisite":null},{"id":"detective","category":"expertise","attribute":"esprit","skill":"investigation","prerequisite":null},{"id":"stable","category":"expertise","attribute":"volonte","skill":"maitrise_spirituelle","prerequisite":null},{"id":"sens_accru_x","category":"expertise","attribute":"volonte","skill":"perception","prerequisite":null},{"id":"maitre_de_la_survie","category":"expertise","attribute":"volonte","skill":"survie","prerequisite":null},{"id":"mental_dacier","category":"expertise","attribute":"volonte","skill":"force_mentale","prerequisite":null},{"id":"neurodriver","category":"expertise","attribute":"volonte","skill":"neurodive","prerequisite":"neurodive_1"},{"id":"seducteur_seductrice","category":"expertise","attribute":"charisme","skill":"seduction","prerequisite":null},{"id":"diplomate","category":"expertise","attribute":"charisme","skill":"diplomatie","prerequisite":null},{"id":"maitre_du_troc","category":"expertise","attribute":"charisme","skill":"commerce","prerequisite":null},{"id":"artiste","category":"expertise","attribute":"charisme","skill":"representation","prerequisite":null},{"id":"autorite_naturelle","category":"expertise","attribute":"charisme","skill":"autorite","prerequisite":null}],"textes":{"codes_corporatifs":{"name":"Codes corporatifs","effect":"+2 Diplomatie pour comprendre et appliquer usages, vocabulaire et hiérarchies corporatives."},"formation_calibree":{"name":"Formation calibrée","effect":"Choisir une Compétence d’Esprit cohérente avec l’éducation reçue ; +1 à cette Compétence."},"culture_produit":{"name":"Culture produit","effect":"Choisir un secteur corporatif : cybernétique, armement, médias, biotech, finance, etc. +2 Savoirs pour connaître acteurs, produits et habitudes du secteur."},"reseau_scolaire":{"name":"Réseau scolaire","effect":"Un Contact mineur issu de l’école, de la formation ou de la corporation familiale."},"toujours_presentable":{"name":"Toujours présentable","effect":"+2 Représentation lorsqu’il faut adopter rapidement le comportement, l’apparence ou le niveau de langage attendu dans un environnement corporatif formel."},"education_civique":{"name":"Éducation civique","effect":"+2 Savoirs sur droit, administration et institutions californiennes."},"procedures_administratives":{"name":"Procédures administratives","effect":"Une fois par scénario, lorsqu’une institution s’apprête à exécuter une décision administrative contre vous ou une personne que vous représentez, vous pouvez exploiter une procédure recevable pour en suspendre l’exécution jusqu’à la fin de la scène, le temps d’un réexamen. Il ne faut pas réussir un second jet pour obtenir ce délai. La suspension peut retarder une saisie, une fermeture, un transfert administratif ou une expulsion ; elle ne désarme pas une intervention face à un danger immédiat. La décision n’est pas annulée : vous disposez d’une fenêtre réelle pour agir, négocier ou apporter une pièce nouvelle."},"famille_de_fonctionnaires":{"name":"Famille de fonctionnaires","effect":"Un Contact mineur dans un service public, une administration ou une force gouvernementale."},"formation_publique":{"name":"Formation publique","effect":"Choisir une Compétence d’Esprit cohérente avec l’éducation reçue ; +1."},"dossier_propre":{"name":"Dossier propre","effect":"Votre identité civile réelle bénéficie d’un crédit de confiance renforcé. Aux contrôles de routine, lorsque votre Logifate et vos pièces correspondent à la situation, leur vérification suffit : pas de fouille approfondie, de retenue ou d’exigence d’un garant provoquées uniquement par un soupçon vague. Le talent vous fait aussi reconnaître comme client ou visiteur fiable dans les démarches ordinaires, sans garantie de faveur financière. Une preuve directe, un mandat ciblé, un objet interdit visible ou une contradiction concrète permettent une investigation normale. Aucun document absent ni fausse identité n’est créé."},"codes_du_milieu":{"name":"Codes du milieu","effect":"+2 Diplomatie pour connaître respect, rites, rangs, tabous et façons correctes de parler dans sa Pègre d’origine."},"omerta_familiale":{"name":"Omerta familiale","effect":"Vous bénéficiez de +2 Force Mentale contre les pressions et intimidations profanes visant directement à vous faire trahir votre famille ou votre ancien milieu. Une fois par scène, vous pouvez relancer une résistance ratée dans ce cadre, hors échec narratif ; vous conservez le second résultat. Le talent protège votre résistance personnelle, pas vos proches eux-mêmes, et ne masque pas vos souvenirs à une lecture mentale directe. Lorsque le même test relève également d’Omerta, leurs deux bonus se cumulent exceptionnellement pour +4, sans troisième bonus équivalent ni deuxième relance de talent."},"enfant_du_quartier":{"name":"Enfant du quartier","effect":"Circonstance favorable (+3) pour retrouver une adresse, un passage ou une figure locale dans le quartier où il a réellement grandi."},"vieilles_frequentations":{"name":"Vieilles fréquentations","effect":"Un Contact mineur lié à la Pègre ou à sa communauté."},"petites_combines":{"name":"Petites combines","effect":"+2 Commerce ou Larcin, choisi à la création, pour de petites pratiques apprises durant l’enfance."},"education_doctrinale":{"name":"Éducation doctrinale","effect":"+2 Savoirs pour la religion dans laquelle le personnage a été élevé."},"vie_communautaire":{"name":"Vie communautaire","effect":"+2 Diplomatie auprès de sa communauté d’origine lorsque les références et coutumes communes sont pertinentes."},"discipline_de_foi":{"name":"Discipline de foi","effect":"+1 Maîtrise spirituelle. Aucun effet de Vérité."},"communaute_dorigine":{"name":"Communauté d’origine","effect":"Un Contact mineur dans une institution ou congrégation religieuse."},"education_caritative":{"name":"Éducation caritative","effect":"+2 Soin, Diplomatie ou Savoirs, choisi à la création, dans les situations d’assistance sociale correspondant réellement à son éducation."},"debrouille":{"name":"Débrouille","effect":"Vous conservez +1 Survie dans les milieux urbains pauvres, abandonnés ou hors système. Pour une tâche non offensive dont vous connaissez la méthode, vous pouvez compenser jusqu’à −3 de malus provenant d’un matériel courant absent ou médiocre en employant des substituts réellement disponibles. Vous ne fabriquez pas un composant indispensable et ne remplacez pas une expertise que vous ne possédez pas."},"codes_de_rue":{"name":"Codes de rue","effect":"+2 Langages & Argot pour argot, signes, graffitis et codes Underlives."},"enfant_des_zones_mortes":{"name":"Enfant des zones mortes","effect":"Circonstance favorable (+3) pour circuler et s’orienter dans son ancien quartier abandonné."},"on_connait_quelquun":{"name":"On connaît quelqu’un","effect":"Un Contact mineur Crawler."},"recuperateur":{"name":"Récupérateur","effect":"+2 Investigation lorsqu’il s’agit de trouver quelque chose d’utile dans des ruines, déchets techniques, squats ou infrastructures abandonnées."},"dotation_standard":{"name":"Dotation standard","effect":"Votre employeur vous confie un lot spécialisé supplémentaire, choisi dans l’équipement autorisé et utile à votre poste, jusqu’à 5 000 $ de valeur catalogue. Il en assure l’entretien courant et le remplacement d’usure. Ce lot s’ajoute aux outils indispensables déjà fournis par le poste ; il ne finance ni véhicule ni augmentation. Il reste propriété de l’employeur et n’est pas revendable. Une perte opérationnelle est traitée par le service, pas remplacée instantanément."},"assurance_corporative":{"name":"Assurance corporative","effect":"La corporation garantit un bien professionnel non unique que vous possédez réellement, inscrit sur la fiche : arme, armure, appareil, augmentation ou véhicule. Une fois par scénario, elle finance sa remise en état après des dommages opérationnels, ou son remplacement à fonction et gamme équivalentes s’il est détruit ou irrécupérable. L’intervention est engagée sans avance de frais, avec le délai matériel ou médical nécessaire. L’objet couvert peut être changé entre deux scénarios, avant les dommages ; il ne peut être assuré rétroactivement. Aucune amélioration de gamme, duplication après récupération de l’original ou destruction volontaire destinée à encaisser une indemnité n’est couverte."},"badge_interne":{"name":"Badge interne","effect":"Vous détenez une accréditation confidentielle réelle au sein de votre corporation. Elle ouvre les sites sécurisés et secrets d’un programme ou d’une branche sensible choisis : laboratoire clandestin, centre d’essai, dépôt protégé ou installation analogue. La sécurité reconnaît votre droit d’entrer et de circuler sans escorte dans ce périmètre ; aucune nouvelle faveur n’est à négocier à chaque visite. Les sites appartenant au même périmètre sont couverts. L’accès physique ne donne ni commandement, ni contrôle universel des systèmes, ni extraction automatique de tous les dossiers compartimentés."},"avantages_salaries":{"name":"Avantages salariés","effect":"Votre contrat prend en charge un deuxième Appui de Sphère corporatif, choisi selon les mêmes catégories, niveaux et limites que l’appui initial. Vous pouvez ainsi disposer d’un logement ET d’un véhicule de fonction, au lieu d’un seul avantage. Les deux prestations existent simultanément et leur prise en charge est inscrite sur la fiche. La même prestation ne peut être comptée deux fois. Ce talent n’ajoute pas d’argent au Compte et ne transfère pas la propriété des biens qui restent sous contrat."},"compte_de_frais":{"name":"Compte de frais","effect":"Dépenses professionnelles raisonnables prises en charge."},"reseau_interne":{"name":"Réseau interne","effect":"Un Contact dans un autre service de la corporation."},"profil_calibre":{"name":"Profil calibré","effect":"Votre corporation vous a spécialement formé pour une Compétence professionnelle de votre Style, choisie et inscrite à l’acquisition. Une fois par scénario, après un échec non narratif à un test de cette Compétence dans une tâche correspondant à votre métier, vous pouvez relancer le 1d10e et conserver le second résultat. Le coût de l’action n’est pas payé une seconde fois et aucun PA n’est créé. Les conditions de formation nécessaires restent applicables ; ce talent n’est pas un point permanent de Compétence."},"acces_fournisseur":{"name":"Accès fournisseur","effect":"Vous accédez directement aux stocks professionnels ordinaires de votre corporation et de ses partenaires désignés, avec réservation et délai annoncé. Vos achats personnels ou professionnels autorisés bénéficient de 10 % de réduction sur le prix catalogue, hors prototypes, pièces uniques et prestations médicales. Cette réduction ne se cumule pas avec une autre remise de statut de même nature : retenir la meilleure. Elle ne s’applique pas aux acquisitions destinées à la revente. Les 5 points de pourcentage de Maître du Troc et le résultat d’une négociation s’ajoutent à cet avantage de statut."},"service_juridique":{"name":"Service juridique","effect":"Assistance légale dans les affaires relevant réellement du travail."},"programme_pilote":{"name":"Programme pilote","effect":"Vous recevez un prototype professionnel réellement jouable, construit sur un équipement de Réalité autorisé par votre fonction. Avant l’acquisition, sa fiche fixe le modèle de base, une amélioration expérimentale exclusive, ses valeurs, ses limites et ses conditions d’entretien. L’amélioration peut être un bonus de +2 à une fonction précisément définie, la suppression de la propriété Encombrant d’un appareil portable compatible, ou une nouvelle fonction concrète validée par le MJ. Ces options sont alternatives, pas cumulées. Le +2 remplace un éventuel bonus équivalent inférieur de la version standard. Un seul prototype est prêté à la fois, sans achat du matériel ; il reste propriété de la corporation. Il peut être remplacé entre deux missions par un autre essai du programme préalablement défini, jamais reconfiguré librement en pleine scène."},"extraction_corporative":{"name":"Extraction corporative","effect":"Une fois par scénario, dans le périmètre réel d’intervention de l’employeur, vous pouvez déclencher une extraction prioritaire. L’autorisation interne est acquise : un moyen de récupération est engagé, avec rendez-vous, capacité et délai annoncés. Il peut emporter vos compagnons dans sa capacité réelle. Vous devez transmettre votre position et rejoindre ou ouvrir un accès praticable. Le talent garantit la mobilisation, pas une arrivée instantanée ni le franchissement automatique d’un blocus."},"requin_corporatif":{"name":"Requin corporatif","effect":"+2 Diplomatie ou Commerce, choisi à l’acquisition, lors de négociations professionnelles entre corporations."},"dotation_de_service":{"name":"Dotation de service","effect":"Le service vous attribue un kit supplémentaire, jusqu’à 5 000 $ d’équipement autorisé par votre fonction, au-delà de votre matériel indispensable. Ce kit peut être échangé au dépôt entre deux missions pour une autre configuration de même plafond ; entretien courant et usure sont pris en charge. Armes, véhicules et augmentations restent soumis à leurs accès propres ; ce lot ne finance ni véhicule ni augmentation. Le matériel doit être restitué et ne peut être vendu."},"habilitation_administrative":{"name":"Habilitation administrative","effect":"Vous possédez une habilitation réelle d’accès aux sites secrets d’un secteur gouvernemental choisi : installations de renseignement, centres techniques protégés, dépôts sécurisés ou établissements analogues. Un contrôle régulier confirme votre autorisation d’y entrer et de circuler dans les zones couvertes, sans demander une faveur au responsable. Le secteur peut regrouper plusieurs sites pertinents. Cette habilitation n’accorde ni commandement, ni accès universel aux fichiers des personnes présentes : les données confidentielles relèvent d’Accès aux registres."},"reseau_administratif":{"name":"Réseau administratif","effect":"Un Contact dans un autre service public."},"acces_aux_registres":{"name":"Accès aux registres","effect":"Choisissez une grande catégorie de données confidentielles : dossiers de police et enquêtes, dossiers médicaux institutionnels, Logifate et historiques administratifs, ou une catégorie comparable pertinente. Vous disposez d’un droit réel de consultation et de recoupement de cette catégorie, y compris hors du besoin ordinaire de votre poste. La consultation d’un dossier identifié ne demande pas un nouveau jet de négociation ; les recherches complexes et l’interprétation peuvent demander Investigation ou Savoirs. L’accès peut passer par un terminal habilité ou une interface sécurisée. Les données inexistantes, détruites ou exceptionnellement compartimentées hors de l’habilitation restent inaccessibles ; l’historique des accès n’est pas supprimé."},"procedure_acceleree":{"name":"Procédure accélérée","effect":"Vous conservez +2 aux tests visant à faire progresser une démarche de votre domaine. Une fois par scénario, vous pouvez obtenir une autorisation provisoire exécutoire immédiatement après un échange avec le service, les validations et formalités détaillées étant régularisées après l’opération. Cela peut permettre le transport d’un témoin, l’usage d’un moyen ordinaire ou une intervention recevable sans attendre le circuit complet. Le service doit avoir compétence pour autoriser l’acte ; le talent ne crée pas une ressource et ne remplace ni une accréditation secrète ni une décision formellement interdite."},"fonctionnaire_experimente":{"name":"Fonctionnaire expérimenté","effect":"Vous conservez +1 Diplomatie dans les rapports professionnels avec l’administration. Une fois par démarche, après un refus discrétionnaire ou une mauvaise orientation, vous obtenez le réexamen du dossier par un responsable compétent sans perdre l’avancement déjà acquis. Cela autorise une nouvelle tentative normalement interdite à situation identique ; un défaut de forme doit être corrigé. Le refus fondé sur une interdiction légale ne peut être contourné ainsi."},"requisition_de_service":{"name":"Réquisition de service","effect":"Pour une mission autorisée, vous pouvez obtenir un moyen supplémentaire disponible : voiture ou utilitaire de service, local utilisable, ou lot matériel d’une valeur maximale de 10 000 $. Un seul moyen est réquisitionné par ce talent à la fois, jusqu’à la fin de la mission. L’affectation ne nécessite pas de négociation de faveur. Le moyen doit exister, pouvoir être confié à votre fonction et être restitué ; conducteur ou spécialiste ne sont pas fournis automatiquement."},"couverture_fonctionnelle":{"name":"Couverture fonctionnelle","effect":"Une fois par scénario, votre institution peut étouffer les conséquences institutionnelles d’une infraction défendable commise pendant une opération ou qu’elle a intérêt à couvrir. Elle fait classer la procédure ordinaire dans son ressort, tolère une initiative irrégulière ou écarte un élément compromettant qu’elle contrôle. Le bénéfice est effectif, sans nouveau jet pour convaincre le protecteur après validation du périmètre. Il ne réécrit ni les faits ni toutes les preuves détenues par des tiers ; une affaire publiquement indéfendable, une trahison ou un acte que l’institution refuse fondamentalement de couvrir reste hors de portée. Le MJ annonce si l’affaire est couverte avant consommation du bénéfice."},"dossier_institutionnel":{"name":"Dossier institutionnel","effect":"Vous disposez d’une identité opérationnelle de couverture entretenue par l’administration, avec les pièces et inscriptions officielles correspondant à une profession ou affectation plausible. Les vérifications ordinaires auprès des organismes couverts confirment cette identité sans remonter automatiquement à votre identité réelle. Une seule couverture est active par ce talent. Le service peut la remplacer entre deux opérations si elle est abandonnée ou compromise ; la nouvelle couverture ne change pas votre visage, vos compétences ni les traces déjà découvertes. Elle ne confère pas d’elle-même les accès secrets d’Habilitation administrative et d’Accès aux registres."},"autorite_officielle":{"name":"Autorité officielle","effect":"+2 Autorité lorsqu’un agent assermenté donne un ordre entrant réellement dans ses prérogatives."},"priorite_interservices":{"name":"Priorité interservices","effect":"Une fois par scénario, vous pouvez obtenir l’engagement coordonné de votre service et d’un autre service compétent sur une opération locale précise. Le résultat doit prendre une forme concrète : sécurisation d’un accès, évacuation, contrôle d’un périmètre, prise en charge de victimes ou autre intervention dans leurs attributions. Un responsable de liaison, un objectif, les moyens engagés et un délai sont annoncés. La rivalité administrative ne peut suffire à refuser. Les agents agissent selon leur hiérarchie et résolvent normalement les dangers ; vous n’obtenez pas un commandement général sur eux ni la neutralisation automatique de toute opposition."},"appui_du_service":{"name":"Appui du service","effect":"Une fois par scénario, pour une mission autorisée, vous choisissez l’affectation d’un spécialiste pour une tâche d’expertise, ou d’une petite équipe de trois agents pour une tâche de terrain relevant de votre service. Leur fonction, leur profil, leur équipement courant et leur délai sont connus avant engagement. Ils peuvent analyser une pièce, surveiller un accès, sécuriser une position, accompagner un transfert ou intervenir techniquement ; ils effectuent leurs propres tests si la tâche est contestée ou dangereuse. L’affectation dure le temps de cette tâche, pas toute la campagne. Une expertise ordinaire matériellement réalisable donne ses conclusions, pas seulement le nom d’un autre interlocuteur."},"protection":{"name":"Protection","effect":"Une fois par scène, lors d’une confrontation où les adversaires peuvent encore choisir de reculer, vous pouvez faire valoir une affiliation criminelle réelle et crédible. Comparez leur Renommée pertinente à la meilleure entre votre Renommée et celle de votre organisation dans ce territoire ; elles ne s’additionnent pas. Si votre valeur est supérieure, un adversaire ou petit groupe qui reconnaît cette protection doit abandonner une intimidation, un racket ou une hostilité limitée et vous laisser vous retirer, sans jet. Face à une Renommée égale ou supérieure, la confrontation se résout normalement ; la réputation invoquée peut fournir la circonstance pertinente. Le talent ne soumet pas une faction en guerre ouverte à votre organisation, ne fait pas oublier une vendetta majeure et ne retire pas des actions de combat à une cible."},"marche_noir":{"name":"Marché noir","effect":"Pour une marchandise illégale non unique et réellement distribuée dans les filières de votre organisation, vous obtenez une offre ferme et la fourniture du bien au prix annoncé, sans mission préalable uniquement destinée à trouver un vendeur ou gagner sa confiance. Un bien courant disponible localement peut être retiré dans la journée ; un bien rare commandable est livré avec un délai annoncé avant engagement : trois jours hors transport exceptionnel annoncé. Le circuit peut fournir un bien interdit au marché ordinaire, sans exiger les justificatifs de vente habituels ; cela ne lève pas les conditions physiques, techniques ou mécaniques nécessaires pour l’utiliser. Marché noir ne fixe pas une remise : Recéleur et Maître du Troc traitent les prix."},"receleur":{"name":"Recéleur","effect":"+2 Commerce pour acheter/vendre des marchandises volées ou illégales via son réseau."},"blanchiment":{"name":"Blanchiment","effect":"Sait faire passer des revenus criminels par une filière légale lorsqu’il possède le réseau nécessaire."},"faussaires":{"name":"Faussaires","effect":"Accès à une filière de faux papiers, identités ou documents."},"dette_de_faveur":{"name":"Dette de faveur","effect":"Vous disposez d’une faveur importante reconnue par un débiteur nommé, dont les moyens et les limites sont définis. L’appeler obtient un service qui demanderait normalement paiement, risque mesuré ou contrepartie, sans nouveau jet de persuasion ni paiement pour le service convenu : cacher temporairement une personne, prêter un véhicule pour une opération, fournir une information confidentielle possédée ou ouvrir une rencontre délicate. Le débiteur fournit le service ou un équivalent dans ses moyens ; il n’est pas tenu au suicide ou à une trahison fondamentale. La faveur est consommée lorsque la prestation est engagée. Après un nouveau service significatif rendu et reconnu, vous pouvez reconstituer une faveur active garantie par ce talent, sans rachat d’XP. Aucune recharge au seul changement de scénario."},"omerta":{"name":"Omerta","effect":"Vous bénéficiez de +2 Force Mentale contre les pressions visant à vous faire trahir votre organisation. Votre cercle professionnel proche et coopérant organise aussi le silence : demandes banales sans réponse sur vos informations sensibles, et alerte en cas de demande ciblée dès qu’il peut vous prévenir. Exception explicite : lorsque le même test relève également d’Omerta familiale, les deux bonus se cumulent pour +4 au total. La relance une fois par scène d’Omerta familiale reste utilisable et bénéficie de ce total. Mental d’acier ne fournit pas un troisième bonus équivalent et aucun test ne bénéficie de plusieurs relances de talent. Trahison d’un associé, contrainte réelle et preuves extérieures restent possibles."},"planque":{"name":"Planque","effect":"Dispose d’un refuge réellement existant associé à son organisation."},"homme_femme_du_milieu":{"name":"Homme/Femme du milieu","effect":"Vous conservez +1 Diplomatie ou Autorité, choisi à l’acquisition, dans votre organisation. Une fois par scénario, elle passe l’éponge sur un écart limité que vous avez commis envers ses règles ou intérêts : négligence, initiative non autorisée, altercation interne mineure ou manquement comparable. La sanction interne normalement attendue est abandonnée, sans nouvelle dette automatique qui remplacerait simplement cette sanction. La faute doit rester réparable et l’organisation doit pouvoir assumer ce pardon ; trahison, pertes majeures ou attaque contre ses dirigeants restent hors de portée. Le pardon interne n’efface pas une procédure menée par une institution extérieure."},"armurier_du_milieu":{"name":"Armurier du milieu","effect":"Votre organisation met à votre disposition une arme non unique de son catalogue disponible, sans prix d’achat, choisie pour l’opération. Vous pouvez la restituer et en changer à l’armurerie entre deux missions. Une seule arme de ce talent est sortie à la fois ; elle reste prêtée et n’est pas revendable. Son entretien courant est pris en charge. Le plafond de valeur est 5 000 $ ; les armes exigeant une installation, un équipage, un accès spécial ou un programme expérimental ne sont pas ouvertes automatiquement. Les munitions restent des consommables payés normalement."},"entreprise_de_couverture":{"name":"Entreprise de couverture","effect":"Possède ou utilise une activité légale pouvant servir de façade."},"corruption_locale":{"name":"Corruption locale","effect":"Un Contact compromis dans une institution précise ; ses capacités restent celles de son véritable poste."},"fiable":{"name":"Fiable","effect":"Vous conservez +2 pour obtenir un contrat grâce à votre réputation professionnelle. Une référence réelle et vérifiable rend ce bonus utilisable auprès d’un nouveau commanditaire. Une fois par scénario, sur un contrat accepté et financé, vous pouvez demander et obtenir une avance de 25 %, sans concession supplémentaire ; elle est déduite du solde. Elle n’est pas versée si vous ne la demandez pas et ne s’ajoute pas à une avance déjà au moins équivalente. Le contrat conserve ses obligations de justification ou de restitution en cas de non-exécution."},"bonnes_adresses":{"name":"Bonnes adresses","effect":"+2 Investigation, Survie ou Commerce pour trouver un service clandestin dans un milieu Crawler où il possède réellement des entrées."},"dans_le_coup":{"name":"Dans le coup","effect":"Vous connaissez les lieux de rencontre et réseaux Neopunks réellement implantés dans la scène que vous fréquentez, ainsi que l’actualité courante qui y circule. Une fois par scénario, vous pouvez demander au MJ un point de situation sur ce milieu, sans quota de questions : qui est banni ou influent, quel groupe monte, où joindre un relais, ou quels mouvements corporatifs connus pourraient le viser. Les réponses distinguent faits, rumeurs et informations encore contradictoires. Les connaissances ordinaires restent disponibles en permanence. Vous pouvez apprendre une menace signalée par le réseau, pas un plan absolument secret inconnu de tous. Connaître un refuge ne garantit pas d’y être accueilli : Nid de frelons fournit cet accueil."},"contact_de_renom":{"name":"Contact de renom","effect":"Un Contact Crawler notable. Son aide n’est jamais automatique."},"assurance_silver":{"name":"Assurance Silver","effect":"Attribue automatiquement une couverture CareForce Silver gratuite dans les Services/Train de vie."},"maitrise_des_codes_de_la_rue":{"name":"Maîtrise des codes de la rue","effect":"Vous conservez +1 Langages & Argot sur la culture Crawler. Après quelques minutes d’observation et d’échanges dans une scène locale accessible, vous identifiez qui y fait réellement autorité, quelle règle de passage ou de respect s’applique et quel comportement risque de provoquer un incident. Ces conclusions portent sur les signes et usages visibles, non sur les intentions cachées. Elles donnent une manière appropriée d’aborder le milieu, pas son amitié automatique."},"optitech":{"name":"OptiTech","effect":"Avec outils et préparation, optimise un matériel pour la scène : il ignore sa première défaillance matérielle non catastrophique."},"logifake":{"name":"Logifake","effect":"Possède un profil Logifate de couverture cohérent résistant aux contrôles ordinaires."},"nid_de_frelons":{"name":"Nid de frelons","effect":"Dans une implantation Neopunk alliée réellement accessible, votre reconnaissance vous donne un accueil discret pour vous et jusqu’à deux compagnons, pendant trois nuits par scénario au total. Le refuge fournit couchage simple, relais de communication et alerte en cas de recherche visible, sans négociation de service à chaque arrivée. Il faut respecter ses règles et ne pas avoir trahi le réseau. Aucun refuge n’apparaît dans une zone dépourvue d’implantation. Changer de refuge ne réinitialise pas les trois nuits."},"insignifiant":{"name":"Insignifiant","effect":"+2 Furtivité pour se fondre dans une foule ; les témoins retiennent difficilement son visage après une interaction banale."},"fixweb":{"name":"Fixweb","effect":"Membre du réseau oral des Fixers ; peut rechercher ou faire circuler des contrats et contacter un intermédiaire local."},"black_clinic":{"name":"Black Clinic","effect":"Une clinique noire ou un réseau Meditech nommé vous reçoit sans exiger de dossier institutionnel compatible. Les urgences bénéficient d’une prise en charge prioritaire selon la gravité, sans attendre une avance financière ; le règlement devient une dette convenue. Les soins ne sont pas automatiquement transmis à une institution extérieure. Honoraires, capacités médicales et risques matériels restent réels : ni implant gratuit, ni guérison impossible, ni effacement des preuves déjà existantes."},"communaute_de_fideles":{"name":"Communauté de fidèles","effect":"Vous disposez d’un réseau local identifié de fidèles volontaires. Une fois par scénario, vous pouvez lui confier une question concrète sur une personne, un lieu ou une activité. En une journée, le réseau rassemble aussi bien les observations de ses membres que les rumeurs qu’ils ont entendues, sans que vous meniez chaque entretien. Il distingue ce qui a été vu, rapporté ou simplement supposé, et indique une provenance exploitable lorsque possible. Le talent peut ainsi faire remonter une information dont les fidèles ne sont pas les témoins directs ; il n’invente pas un secret qui ne circule nulle part et n’impose pas aux fidèles une infiltration dangereuse."},"autorite_religieuse":{"name":"Autorité religieuse","effect":"+2 Autorité ou Diplomatie auprès de croyants reconnaissant réellement sa fonction."},"ministere":{"name":"Ministère","effect":"Vous connaissez un domaine confidentiel des activités de votre religion, choisi à l’acquisition : exorcistes, protection de reliques, ordres de Chasse présentés comme unités spécialisées, dossiers d’incidents ou dispositifs analogues. Vous savez qu’ils existent, comment reconnaître leurs principaux signes institutionnels et quel canal réel contacter pour leur signaler un cas ou leur poser une question. Vous connaissez une partie de leurs méthodes et explications profanes, pas automatiquement leurs pouvoirs ou la véritable nature des créatures. Cette préparation accorde +2 au premier test de Stress provoqué par la confrontation avec un phénomène correspondant à ce domaine, par scénario. Aucun passage automatique de Profane à Initié ni talent de Vérité n’est accordé."},"mission_ecclesiastique":{"name":"Mission ecclésiastique","effect":"Une fois par scénario, l’institution mandate une mission extérieure compatible avec votre rôle, y compris sur une proposition que vous lui soumettez. Elle fournit une lettre de mission et prend en charge jusqu’à 1 000 $ de frais justifiés de déplacement, hébergement et logistique, pour vous et vos accompagnants dans cette enveloppe commune. Le mandat donne une légitimité institutionnelle à votre présence ; il ne constitue ni immunité, ni droit d’entrée forcée, ni revenu personnel supplémentaire."},"hebergement_religieux":{"name":"Hébergement religieux","effect":"Une implantation réelle met durablement à votre disposition un espace simple pour vous et jusqu’à deux compagnons, avec rangement privatif verrouillable. Le logement et ses charges ordinaires sont pris en charge tant que le lien institutionnel est maintenu. La capacité convenue est réservée, et ne dépend pas chaque soir des places d’hospitalité restantes. Ce n’est ni une propriété revendable ni une planque secrète. Un loyer équivalent compté séparément est supprimé, sans hausse automatique du Train de vie."},"reseau_caritatif":{"name":"Réseau caritatif","effect":"Une fois par scénario, vous pouvez faire engager une opération caritative locale réelle, en choisissant l’un des deux usages suivants. Mise à l’abri : un moyen de transport accessible prend en charge jusqu’à cinq personnes en difficulté et les confie au réseau pour sept jours d’hébergement simple, de repas et de soins ordinaires disponibles. Couverture d’intervention : un convoi, une distribution ou un dispositif d’assistance réel vous intègre, avec jusqu’à deux compagnons aptes à y participer, pour rejoindre une zone ou des interlocuteurs accessibles à cette mission humanitaire. Le déplacement, le responsable et la mission sont annoncés ; il ne s’agit pas seulement d’une adresse d’association. Aucun blocus inviolable n’est franchi automatiquement, aucun accès secret n’est créé et l’opération doit rester compatible avec l’aide réellement fournie."},"education_theologique":{"name":"Éducation théologique","effect":"Vous conservez +1 Savoirs sur religion, doctrine et histoire religieuse. Une fois par scène, devant des auditeurs reconnaissant la doctrine concernée, vous pouvez dénoncer une contradiction précise entre les actes ou ordres d’un interlocuteur et les obligations qu’il revendique. Sous pression, cela prend 1 PA et un test Esprit + Savoirs + 1d10e contre Charisme + Autorité + 1d10e de l’interlocuteur. En réussite, il subit −3 à ses tests d’Autorité fondés sur cette légitimité religieuse devant cet auditoire jusqu’à la fin de la scène. Les auditeurs restent libres de leurs convictions et peuvent le suivre pour d’autres raisons ; ses pouvoirs éventuels ne disparaissent pas. Une seule contestation réussie de ce talent est comptée contre la même légitimité dans la scène."},"conseiller_spirituel":{"name":"Conseiller spirituel","effect":"Vous conservez +1 Diplomatie auprès d’une personne acceptant votre conseil. Après dix minutes d’échange réel sur une épreuve précise, elle peut relancer une fois un test de Stress raté face à cette épreuve avant la fin du scénario, hors échec narratif ; le second résultat est conservé. Une seule personne peut bénéficier à la fois de votre préparation, qui ne se cumule pas avec une autre relance du même test. Ni Trauma durable ni minima dus aux blessures ne sont supprimés."},"presence_holonet":{"name":"Présence Holonet","effect":"+2 Investigation ou Représentation dans les réseaux médiatiques officiels de sa religion."},"soutien_communautaire":{"name":"Soutien communautaire","effect":"Sait mobiliser rapidement une aide profane modeste : bénévoles, repas, transport, traduction, collecte…"},"ordre_religieux":{"name":"Ordre religieux","effect":"L’Ordre vous attribue un correspondant spécialisé dans une discipline choisie et documentée. Une fois par scénario, vous obtenez une consultation ou expertise de cette discipline prise en charge : examen d’un dossier, diagnostic, analyse ou préparation professionnelle compatible. Le spécialiste accomplit le travail et fournit ses conclusions, avec ses propres tests si nécessaire. Entre les missions, il peut aussi assurer un enseignement cohérent. Aucun talent, rang ou point de Compétence n’est acquis gratuitement."},"reseau_confessionnel":{"name":"Réseau confessionnel","effect":"Dans une implantation alliée existante où vous arrivez, le réseau vous fournit une recommandation vérifiable et un répondant local qui accepte une première rencontre. Celui-ci peut vous présenter à un interlocuteur pertinent de son environnement, y compris extérieur à votre religion, lorsqu’il dispose réellement de cette relation. La recommandation remplace l’absence de présentation et la méfiance liée au seul fait d’être inconnu ; elle ne garantit ni faveur, ni accord politique, ni ressources exceptionnelles."},"sommeil_leger":{"name":"Sommeil léger","effect":"+2 Perception pour remarquer un danger pendant le sommeil. Un danger évident réveille normalement le personnage."},"resistance_a_la_chaleur":{"name":"Résistance à la chaleur","effect":"+2 Constitution contre chaleur, déshydratation et exposition climatique chaude."},"resistance_au_froid":{"name":"Résistance au froid","effect":"+2 Constitution contre froid et exposition climatique glaciale."},"sante_de_fer":{"name":"Santé de fer","effect":"Vous bénéficiez de +2 Constitution contre les maladies et infections. Chaque période de 24 heures comportant le repos nécessaire vous rend 2 PV supplémentaires, ajoutés après les éventuels multiplicateurs de récupération. Ce bénéfice ne modifie ni vos PV maximum, ni les soins instantanés, ni les tests d’Agonie."},"insensibilite_a_la_douleur":{"name":"Insensibilité à la douleur","effect":"La douleur seule n’impose ni malus ni interruption à une action que vous restez physiquement capable d’exécuter. Tant que vos PV sont positifs, calculez le Stress minimal imposé par vos blessures un cran moins sévèrement : Tendu devient Normal ; Paniqué devient Tendu. Un Stress psychologique indépendant reste applicable : retenez le plus grave des états encore imposés. Les blessures, incapacités réelles, l’Agonie et la mort ne changent pas."},"nageur":{"name":"Nageur","effect":"+1 Athlétisme pour nage et manœuvres aquatiques ; pleine mobilité dans une eau ordinaire."},"ambidextre":{"name":"Ambidextre","effect":"Vous utilisez indifféremment vos deux mains. Une fois par round, pendant votre activation, vous pouvez dépenser 1 PA pour une attaque double avec deux armes à une main que vous pouvez réellement manier : deux armes de contact ou deux armes à feu employées en tir simple. Déclarez une même cible pour les deux attaques, puis effectuez deux jets séparés, chacun avec −3. Chaque attaque réussie applique ses dégâts et l’Armure normalement ; les défenses se résolvent selon leurs règles ordinaires. L’attaque double ne bénéficie ni de Viser, ni de Rafale, ni de Suppression, et ne se déclenche pas pendant une riposte. Les autres attaques du round n’utilisent qu’une arme par PA. Aucune réserve de PA n’est augmentée."},"brave":{"name":"Brave","effect":"+2 Maîtrise spirituelle face à la peur d’un danger physique identifiable."},"fier_heritier":{"name":"Fier héritier","effect":"Augmente le Train de vie de base d’un cran, avec un minimum Confortable ; peut exceptionnellement faire passer Aisé à Luxe. Luxe n’est pas un niveau de départ ordinaire : ce talent constitue l’exception. Aucun versement libre n’est ajouté au Compte."},"renomme":{"name":"Renommé","effect":"Votre Renommée augmente de 1 dans son milieu de référence, dans la limite de 5. Ce talent non répétable applique les bénéfices de la règle générale de Renommée. À 5, aucune progression supplémentaire ne peut être achetée avec ce talent."},"presence_remarquable":{"name":"Présence remarquable","effect":"Choisir un trait particulièrement frappant : beauté, voix, allure, style, carrure… +2 au test social lorsque ce trait précis constitue réellement un avantage."},"apprentissage_fulgurant":{"name":"Apprentissage fulgurant","effect":"Une fois par scénario, réduit de 2 XP le coût d’une hausse de Compétence réellement pratiquée ou entraînée pendant ce scénario, minimum 1 XP."},"athlete":{"name":"Athlète","effect":"+1 Athlétisme. En opposition purement athlétique, une égalité peut être départagée à son avantage lorsque l’entraînement constitue la différence."},"poings_de_fer":{"name":"Poings de fer","effect":"+1 Pugilat. Les attaques à mains nues ont DGT 2 au lieu de 1."},"stabilite_augmentique":{"name":"Stabilité augmentique","effect":"+1 Humanité. Le Stress augmentique de base total est réduit de 1, minimum 0."},"maitre_des_lames":{"name":"Maître des lames","effect":"Vous bénéficiez de +1 aux tests de Mêlée avec une lame. Sur une attaque réussie avec marge 6+, infligeant au moins 1 PV à une cible capable de saigner, vous pouvez choisir une plaie persistante comme Altération. Elle fait perdre 2 PV à la fin du round suivant, puis de chaque round, jusqu’à une compression accessible de 1 PA ou un soin approprié. Une seule plaie de ce talent agit par cible. L’Armure n’est pas appliquée une seconde fois à cette perte de PV et aucune autre Altération gratuite n’est ajoutée."},"resistance_aux_toxines":{"name":"Résistance aux toxines","effect":"+2 Constitution contre poisons, drogues, toxines et substances similaires."},"tireur_de_precision":{"name":"Tireur de précision","effect":"Vous bénéficiez de +1 Tir. Une fois par round, juste avant un tir simple de votre activation, vous pouvez Viser sans dépenser le PA normalement requis. Cette visée apporte le +3 normal au tir concerné et les possibilités ordinaires de localisation si une Altération est obtenue. Le tir coûte toujours son PA. Une seconde visée sur ce même tir ne double pas le bonus ; pour d’autres tirs du round, Viser conserve son coût normal. Rafale, Suppression et l’attaque double d’Ambidextre restent incompatibles avec Viser. Le seuil normal d’Altération n’est pas abaissé."},"pilote_emerite":{"name":"Pilote émérite","effect":"+1 Pilotage. Gagne les égalités d’opposition lorsque la maîtrise du véhicule est réellement déterminante."},"ombre_vivante":{"name":"Ombre vivante","effect":"+1 Furtivité. +2 lorsqu’il vient de rompre la ligne de vue et exploite immédiatement un environnement permettant de disparaître."},"reflexes_defensifs":{"name":"Réflexes défensifs","effect":"Vous bénéficiez de +1 aux tests d’Esquive et pouvez effectuer une Défense active même en étant surpris. Vous payez normalement 1 PA et devez être physiquement capable de vous défendre. Si l’attaque ouvre le combat, ce PA est décompté de votre réserve du premier round. Le talent lève seulement l’interdiction liée à la Surprise : il ne donne aucun PA et n’autorise pas une défense interdite pour une autre raison. Le +1 aux tests ne recalcule pas la Défense passive."},"mains_lestes":{"name":"Mains lestes","effect":"+1 Larcin. +2 pour pickpocket, manipulation discrète ou dissimulation d’un petit objet."},"linguiste_emerite":{"name":"Linguiste émérite","effect":"+1 Langages & Argot. Peut déduire le sens général d’une langue inconnue apparentée à une langue connue."},"puits_de_savoir":{"name":"Puits de savoir","effect":"Vous bénéficiez de +1 Savoirs et choisissez un grand domaine de connaissance. Dans ce domaine, les faits ordinaires que vous avez réellement appris sont rappelés sans test de mémoire. Lors d’une recherche spécialisée, votre travail personnel de lecture, comparaison et analyse demande deux fois moins de temps. L’accès aux documents, les délais externes et les tests nécessaires pour interpréter une question difficile restent inchangés."},"doc_de_choc":{"name":"Doc de choc","effect":"+1 Soin. Les Premiers soins réussis rendent +1 PV supplémentaire."},"mecano_de_pointe":{"name":"Mécano de pointe","effect":"+1 Mécanique. Diagnostic, démontage et compréhension d’une machine accessible demandent environ deux fois moins de temps."},"detective":{"name":"Détective","effect":"+1 Investigation. Sur DR 2+, une enquête réussie révèle normalement un détail ou lien supplémentaire pertinent lorsque la scène en contient un."},"stable":{"name":"Stable","effect":"Vous bénéficiez de +1 Maîtrise spirituelle aux tests de Stress. Une fois par scène, après un échec non narratif à un tel test, vous réduisez d’un cran l’aggravation qu’il devait provoquer, sans descendre sous votre état précédent. Normal → Tendu reste Normal ; Normal → Paniqué devient Tendu ; Tendu → Paniqué reste Tendu. Les autres conséquences de l’échec subsistent. Ce bénéfice ne modifie ni les minima dus aux blessures ni un état imposé sans test."},"sens_accru_x":{"name":"Sens accru (X)","effect":"Choisir vue, ouïe, odorat, toucher ou goût. +2 Perception lorsque ce sens précis est déterminant."},"maitre_de_la_survie":{"name":"Maître de la survie","effect":"Vous bénéficiez de +1 Survie. Une action réussie de collecte d’eau, de recherche de nourriture ou d’installation d’abri peut satisfaire jusqu’à cinq personnes, vous compris, sans multiplier les tests ni le temps consacré à cette même tâche par le nombre de bénéficiaires. Il doit réellement exister assez de ressources ou d’espace. Une collecte ne fournit pas simultanément les autres besoins qui n’ont pas été traités."},"mental_dacier":{"name":"Mental d’acier","effect":"+1 Force Mentale. +2 contre interrogatoire, pression psychologique ou tentative profane de briser sa volonté ; prendre le meilleur bonus applicable."},"neurodriver":{"name":"Neurodriver","effect":"Prérequis Neurodive 1+. +1 aux tests de Neurodive et +1 Neuroprogramme chargé. Ne modifie jamais le Rang Neurodive."},"seducteur_seductrice":{"name":"Séducteur / Séductrice","effect":"+1 Séduction. Après une interaction suffisamment longue et réussie, distingue généralement attirance sincère, indifférence et séduction intéressée."},"diplomate":{"name":"Diplomate","effect":"Vous bénéficiez de +1 Diplomatie. Après quelques échanges réels, vous pouvez demander quelle concession concrète, garantie ou modification de proposition pourrait faire avancer la négociation, d’après les positions et indices exposés. Le MJ fournit une piste praticable, ou indique qu’aucun compromis ne ressort de ces échanges. Ce diagnostic ne révèle pas de pensée secrète : vous devez encore pouvoir offrir la concession et conclure l’accord."},"maitre_du_troc":{"name":"Maître du Troc","effect":"Vous bénéficiez de +1 Commerce. Lors d’un achat, vous obtenez 5 points de pourcentage supplémentaires de réduction sur le prix de référence de la transaction ; lors d’une vente, vous obtenez 5 points de pourcentage supplémentaires de majoration sur le prix de reprise de référence. Ce bénéfice est fixe, s’applique même si aucun jet n’est nécessaire et s’ajoute au résultat d’une négociation. Il se cumule aussi avec Accès fournisseur lorsqu’il s’applique : sa remise de statut et cet avantage de négociateur sont distincts. Les autres remises de statut équivalentes restent soumises à leur règle du meilleur bonus. Le talent ne crée ni acheteur ni obligation de conclure et ne multiplie pas son effet lorsqu’on fractionne la même transaction."},"artiste":{"name":"Artiste","effect":"+1 Représentation. Une représentation réussie peut créer une circonstance favorable (+3) lors d’une interaction ultérieure directement influencée."},"autorite_naturelle":{"name":"Autorité naturelle","effect":"+1 Autorité. +2 pour donner immédiatement une consigne simple à un groupe qui reconnaît déjà une légitimité au personnage."}}}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
