INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('desavantage', 'creation', 'attribute.neurocompatibilite_nulle', 'Neurocompatibilité nulle', NULL, '{"nature":"creation","groupe":"attribute","id":"neurocompatibilite_nulle","effect":"Dès qu’au moins une augmentation génère du Stress, le Stress augmentique de base total augmente de +2.","category":"attribute","attribute":"vigueur"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
