INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('desavantage', 'creation', 'sphere.religieuse.devoir_pastoral', 'Devoir pastoral', NULL, '{"nature":"creation","groupe":"sphere.religieuse","id":"devoir_pastoral","effect":"Responsable d’une communauté, de fidèles ou de personnes vulnérables.","category":"sphere","sphere":"religieuse"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('desavantage', 'creation', 'sphere.religieuse.sous_surveillance_ecclesiastique', 'Sous surveillance ecclésiastique', NULL, '{"nature":"creation","groupe":"sphere.religieuse","id":"sous_surveillance_ecclesiastique","effect":"Un supérieur, conseil ou service interne doute de lui.","category":"sphere","sphere":"religieuse"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('desavantage', 'creation', 'sphere.religieuse.vu_interdit', 'Vœu / Interdit', NULL, '{"nature":"creation","groupe":"sphere.religieuse","id":"vu_interdit","effect":"Choisir une règle religieuse réellement contraignante ; violation consciente rend Tendu jusqu’à réconciliation/pénitence.","category":"sphere","sphere":"religieuse"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'creation', 'edge', 'Edge et désavantages', NULL, '{"nature":"creation","edge":{"base":5,"maxHeld":8,"options":{"attributePack":{"max":1,"points":2},"skillPacks":{"max":3,"points":4},"talentPacks":{"max":2,"points":1},"cashPacks":{"max":3,"amount":5000},"lifestylePack":{"max":1,"steps":1},"augmentationPacks":{"max":2,"amount":5000,"gen2Windows":1},"renownPack":{"max":1,"points":1}},"lore":{"attributePack":{"lore":"Le personnage révèle un potentiel physique, mental ou social supérieur à ce que sa répartition initiale laissait encore apparaître.","mechanic":"1 Edge · +2 points d’Attribut à répartir ici · maximum 1 fois · plafond final 7."},"skillPacks":{"lore":"Une formation supplémentaire, des années de pratique ou un domaine travaillé plus sérieusement donnent au personnage davantage de savoir-faire dès le départ.","mechanic":"1 Edge · +4 points de Compétence à répartir ici · maximum 3 fois · plafond 5."},"talentPacks":{"lore":"Une expérience, une disposition rare ou un apprentissage marquant ajoute un Talent de Réalité au bagage initial du personnage.","mechanic":"1 Edge · +1 Talent de Réalité · maximum 2 fois. Commun, Expertise, Origine ou Sphère si l’accès reste cohérent."},"cashPacks":{"lore":"Épargne, prime, héritage liquide, vente récente ou réserve professionnelle donnent au personnage davantage de moyens immédiatement mobilisables.","mechanic":"1 Edge · +5 000 $ au Compte · maximum 3 fois."},"lifestylePack":{"lore":"Le personnage dispose d’une situation matérielle plus confortable et durable que son seul Style ne le laisserait supposer.","mechanic":"1 Edge · +1 cran de Train de vie · maximum 1 fois · maximum Aisé par Edge."},"augmentationPacks":{"lore":"Une meilleure couverture médicale, un sponsor ou un investissement antérieur a permis davantage d’augmentations et l’accès à une technologie Gen2 supplémentaire.","mechanic":"1 Edge · +5 000 $ d’Enveloppe augmentique et +1 fenêtre Gen2 · maximum 2 fois."},"renownPack":{"lore":"Le personnage arrive déjà avec un nom qui circule dans un milieu précis : réputation professionnelle, exploits, œuvre publique ou notoriété locale.","mechanic":"1 Edge · +1 Renommée de départ · maximum 1 fois · Renommée initiale maximum 2."}}}}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'creation', 'aides', 'Textes d''aide de la création', NULL, '{"nature":"creation","lore":{"origin":{"corporatiste":"Vous avez grandi dans un environnement où école, logement, soins, carrière et réputation pouvaient dépendre d’une corporation ou de son écosystème.","gouvernementale":"Votre éducation s’est faite au contact des institutions, des services publics, des procédures et de l’idée qu’une fonction officielle implique aussi des responsabilités.","mafieuse":"Vous avez grandi dans un milieu où les liens, les dettes, la réputation et les règles non écrites pouvaient compter davantage qu’un texte de loi.","religieuse":"Votre enfance ou votre formation s’est structurée autour d’une communauté de foi, de ses rites, de son entraide et de ses institutions.","crawler":"Vous avez appris à vivre dans les marges, les zones oubliées ou l’Underlife, en comptant davantage sur la débrouille et les relations que sur une institution stable."},"originTalent":{"codes_corporatifs":"Très tôt, vous avez appris qu’un titre oublié, une formule maladroite ou le mauvais niveau de langage peut fermer une porte avant même la négociation.","formation_calibree":"Votre cursus a été pensé comme un investissement : on vous a donné tôt une compétence dans laquelle devenir utile.","culture_produit":"Les marques, acteurs et habitudes d’un secteur ont fait partie de votre environnement presque comme une culture familiale.","reseau_scolaire":"Un ancien camarade, formateur ou proche du milieu professionnel est resté dans votre carnet d’adresses.","toujours_presentable":"Vous avez appris à ajuster tenue, registre et comportement avant même de franchir la porte.","education_civique":"Les institutions n’étaient pas abstraites : on vous a appris leur vocabulaire, leurs règles et la façon dont elles sont censées fonctionner.","procedures_administratives":"Vous avez appris où une décision doit encore attendre sa validation. Un recours recevable vous donne du temps lorsque quelqu’un cherche à vous mettre devant le fait accompli.","famille_de_fonctionnaires":"Quelqu’un de votre entourage porte encore un badge, un uniforme ou travaille derrière un bureau officiel.","formation_publique":"Une école, un programme ou une structure publique vous a transmis une spécialité concrète.","dossier_propre":"Vos traces civiles inspirent une confiance qui écourte les contrôles ordinaires. Votre véritable identité tient sans que chaque interlocuteur vous traite comme un suspect à démasquer.","codes_du_milieu":"Vous avez appris qui saluer, quand vous taire et à quel moment une plaisanterie devient une offense.","omerta_familiale":"La loyauté familiale est devenue une discipline intime. Même quand la pression trouve une faille, vous pouvez encore vous reprendre avant de livrer les vôtres.","enfant_du_quartier":"Vous connaissez encore les raccourcis, les visages et les portes qui n’ont jamais eu besoin d’adresse.","vieilles_frequentations":"Un ancien du quartier ou du milieu décroche encore lorsque votre nom s’affiche.","petites_combines":"Vous avez grandi avec les petits arrangements, les marges et les objets qui changent discrètement de propriétaire.","education_doctrinale":"Les textes, rites et débats de votre tradition ont fait partie de votre éducation ordinaire.","vie_communautaire":"Vous savez parler à ceux qui partagent les mêmes références, habitudes et façons de faire communauté.","discipline_de_foi":"Prière, méditation ou discipline rituelle vous ont appris à retrouver un centre lorsque la pression monte.","communaute_dorigine":"Quelqu’un dans votre ancienne communauté se souvient encore de vous, de votre famille ou de ce que vous y avez fait.","education_caritative":"Vous avez appris à aider concrètement : soigner, orienter, expliquer et rester présent quand quelqu’un est dans le besoin.","debrouille":"Vous avez grandi avec des moyens incomplets. Savoir détourner ce qui se trouve autour de vous permet de continuer quand le bon équipement manque.","codes_de_rue":"Tags, gestes, surnoms et expressions de l’Underlife forment pour vous une seconde grammaire.","enfant_des_zones_mortes":"Vous avez grandi là où les plans officiels cessent d’être vraiment utiles.","on_connait_quelquun":"Dans les marges, survivre signifie souvent savoir qui appeler avant de savoir quoi faire.","recuperateur":"Là où d’autres voient des déchets, vous voyez encore des pièces, des usages et des opportunités."},"sphere":{"corporatiste":"Les corporations ont reconstruit, nourri, équipé et employé une immense part de la population. Certaines fonctionnent presque comme des sociétés miniatures : elles apportent stabilité, technologie et services, au prix d’une vie de plus en plus liée au contrat de travail.","gouvernementale":"La Californie a reconstruit un État assez puissant pour ne pas devenir une simple propriété corporative. Police, armée, secours, administration et renseignement donnent de vrais moyens — avec une hiérarchie, des procédures, un mandat et des comptes à rendre.","mafieuse":"La Pègre moderne mêle familles, territoires, entreprises légales, réseaux clandestins et influence politique. Elle fournit protection, crédit, travail et marchandises là où l’État s’efface ; dans ce monde, un nom ou une dette peut peser davantage qu’un contrat écrit.","crawler":"Les Crawlers vivent entre les systèmes : mercenaires, Neurodivers, Meditechs, fixers, pilotes, récupérateurs ou artistes. Ils travaillent par contrat, réputation et relations ; leur liberté est réelle, mais lorsqu’une situation s’effondre ils ont rarement une institution derrière eux.","religieuse":"Les crises ont rendu aux religions une forte fonction sociale : accueil, soins, aide, communauté, éducation, protection et parfois forces armées. Cette Sphère dépasse largement le clergé et inclut aussi médecins, logisticiens, spécialistes du Holonet, administrateurs et combattants."},"style":{"manucorpo":"Professionnel de l’industrie, de l’ingénierie et de la production : vous faites fonctionner ateliers, chaînes, machines, infrastructures et logistique technique.","biocorpo":"Spécialiste du biomédical, de la génétique et des biotechnologies : votre quotidien se joue entre organismes vivants, diagnostics, protocoles et laboratoire.","cybercorpo":"Spécialiste cyber, neuro, IA ou cybersécurité : vous travaillez là où les réseaux, les augmentations et l’information deviennent une même infrastructure.","armacorpo":"Agent de sécurité ou de combat corporatif : protection de sites, escorte, intervention et usage professionnel de la force font partie du métier.","servicorpo":"Professionnel des services, des affaires, de la clientèle ou du management : vous savez faire circuler personnes, informations, contrats et décisions.","forces_armees":"Soldat, marin ou pilote militaire : votre formation privilégie discipline collective, engagement armé, mobilité et chaîne de commandement.","agent_gouvernemental":"Policier, enquêteur, agent de renseignement ou d’agence : vous combinez procédure, collecte d’information, surveillance et capacité d’intervention.","net_corps":"Opérateur de cybercombat et de guerre électronique : votre champ de bataille est autant le Holonet que les systèmes connectés d’un théâtre d’opérations.","service_public":"Professionnel de santé, du secours ou d’un service technique : vous maintenez les personnes et les infrastructures lorsque la situation cesse d’être confortable.","diplomate_administrateur":"Diplomate ou haut administrateur : négociation, représentation, langues, droit pratique et fonctionnement institutionnel structurent votre travail.","soldato":"Homme de main, garde ou combattant de la Pègre : vous protégez des intérêts, faites respecter des décisions et survivez aux guerres entre organisations.","tueur_a_gages":"Professionnel de l’assassinat, de l’infiltration et de la traque : repérer, approcher et frapper sans offrir de seconde chance constitue votre savoir-faire.","hacker":"Cybercriminel spécialisé dans les données, l’intrusion, le vol et le chantage : l’information est pour vous une cible, une arme et une monnaie.","charcudoc":"Médecin clandestin et technicien d’implants : vous soignez, modifiez et réparez loin des circuits propres, souvent avec des patients qui ne peuvent pas poser de questions.","affairiste_bookmaker":"Intermédiaire de finance, paris, corruption et blanchiment : vous transformez relations, argent gris et information en leviers utilisables.","deathrunner_merc":"Mercenaire habitué aux contrats violents : quand la négociation échoue ou n’a jamais été prévue, vous êtes payé pour terminer le travail.","neurodiver":"Intrus du Holonet et spécialiste de l’information : vous ouvrez des systèmes, explorez leurs défenses et revenez avec ce que quelqu’un voulait garder caché.","meditech":"Soignant-technicien de terrain et des Black Clinics : vous mêlez médecine, mécanique et augmentique dans des conditions rarement idéales.","gundriver":"Pilote de route, convoyeur et transporteur sous risque : le véhicule est votre outil principal, votre protection et souvent une partie de votre réputation.","neopunk":"Agitateur, artiste et organisateur de réseau : vous faites circuler idées, images, contacts et contestation dans l’Underlife comme sur le Holonet.","ordre_arme":"Soldat ou garde d’une institution religieuse : votre fonction est de protéger personnes, lieux, convois ou intérêts confessionnels lorsque la foi seule ne suffit plus.","clerc_holonet":"Spécialiste de communication, doctrine numérique et réseaux : vous portez la parole d’une institution dans les espaces connectés et savez y défendre sa présence.","ministeriel":"Professionnel des ressources, de la santé, des sciences ou des infrastructures d’une institution religieuse : vous êtes le bras technique et logistique de son action.","clerc_administrateur":"Prédicateur, responsable communautaire ou administrateur : vous entretenez la cohésion, la parole publique et le fonctionnement quotidien de l’institution.","missionnaire":"Agent de terrain, d’assistance et d’implantation : vous allez là où l’institution est faible ou absente, avec assez de polyvalence pour y rester."},"skill":{"athletisme":"Course, saut, escalade et effort physique soutenu. Athlétisme entre directement dans l’Initiative avec l’Agilité et dans le Déplacement : 5 + Athlétisme mètres par PA.","pugilat":"Combat à mains nues, coups, prises et techniques corporelles. Une attaque de Pugilat utilise Vigueur + Pugilat + 1d10e.","humanite":"Continuité du moi, libre arbitre et capacité à rester soi malgré transformations et altérations du corps. Humanité entre dans l’Intégrité avec Force Mentale et fixe aussi, avec Vigueur, le Stress augmentique maximum.","melee":"Usage offensif des armes de contact : lames, matraques et autres armes de mêlée. Une attaque utilise Vigueur + Mêlée + 1d10e.","constitution":"Endurance organique, récupération et résistance générale du corps. Constitution augmente les PV maximum, repousse le seuil de mort et détermine les PV récupérés par jour de repos normal.","tir":"Usage des armes à distance et maîtrise du tir sous pression. Une attaque de Tir utilise Agilité + Tir + 1d10e avant les règles propres à l’arme, au couvert et à la visée.","pilotage":"Conduire et manœuvrer véhicules terrestres, aériens ou autres engins lorsqu’un véritable test est nécessaire : vitesse, poursuite, manœuvre risquée ou terrain difficile.","furtivite":"Se déplacer, agir et se positionner sans être repéré ; exploiter ombres, bruit ambiant, couvert et timing pour éviter l’attention.","esquive":"Éviter physiquement une attaque ou un danger immédiat. Esquive construit la Défense passive avec Agilité et sert aussi à la Défense active lorsqu’elle est utilisée.","larcin":"Vol discret, pickpocket, manipulation clandestine d’objets, serrures et petites techniques de cambriolage ou de fraude matérielle.","mecanique":"Diagnostiquer, réparer, modifier et comprendre machines, véhicules, systèmes techniques et une partie de l’augmentique lorsqu’une intervention matérielle est nécessaire.","langages_argot":"Langues, jargons, codes sociaux et argots spécialisés. À la création, chaque point permet de connaître une langue supplémentaire en plus de la langue native.","savoirs":"Connaissances théoriques, culture générale et domaines spécialisés : droit, sciences, institutions, histoire, religions, secteurs techniques ou corporatifs selon le contexte.","soin":"Premiers secours, diagnostic et pratique médicale. Les premiers soins utilisent Esprit + Soin ; en réussite standard, ils peuvent rendre 1 + DR PV selon les règles de Santé.","investigation":"Chercher méthodiquement des indices, recouper des informations, inspecter une scène et reconstruire ce qui s’est passé à partir de traces exploitables.","neurodive":"Accès, intrusion et navigation active dans le Holonet et les systèmes connectés. Les Neuroprogrammes fournissent les outils spécialisés ; le Rang de Neurodive détermine aussi combien peuvent être chargés.","perception":"Repérer détails, mouvements, sons, changements et menaces dans l’environnement ; remarquer ce qui pourrait passer inaperçu sans une attention volontaire.","maitrise_spirituelle":"Garder le contrôle de soi sous Stress, peur, surcharge ou crise. Elle intervient notamment avec Volonté dans les tests de Stress et plusieurs sorties de Frénésie.","survie":"S’orienter, trouver un abri ou des ressources, gérer les contraintes du terrain et continuer à fonctionner loin d’un environnement sûr ou familier.","force_mentale":"Résister à la pression mentale et aux attaques occultes. Avec Volonté elle forme la Défense occulte passive — également Défense Neuro passive dans le Holonet — et avec Humanité elle détermine l’Intégrité.","seduction":"Créer ou exploiter une attraction personnelle, lire le registre du désir et établir une proximité lorsque cette approche est réellement pertinente à la scène.","diplomatie":"Négocier, désamorcer un conflit, trouver un compromis et manier les codes relationnels d’un milieu sans simplement imposer son autorité.","commerce":"Évaluer, négocier, acheter, vendre et comprendre les pratiques d’un marché, y compris lorsqu’il faut marchander ou sentir qu’une transaction cache autre chose.","representation":"Jouer un rôle, se produire, maîtriser son image et son comportement public : scène, média, apparence professionnelle ou performance sociale selon le contexte.","autorite":"Commander, obtenir l’obéissance, poser un cadre et faire peser son statut ou sa présence lorsqu’une relation hiérarchique ou un rapport de force social le permet."},"attribute":{"vigueur":"Puissance physique, robustesse et capacité du corps à encaisser l’effort. La Vigueur participe notamment aux PV maximum, au seuil de mort, au Stress augmentique maximum et aux attaques de Mêlée ou de Pugilat.","agilite":"Coordination, vitesse d’exécution et précision corporelle. L’Agilité participe à l’Initiative, à la Défense, au Tir et à de nombreuses actions demandant réflexes ou contrôle fin.","esprit":"Analyse, mémoire, raisonnement et maîtrise technique. L’Esprit soutient les savoirs, l’enquête, la médecine, la mécanique et la compréhension méthodique d’un problème.","volonte":"Concentration, stabilité intérieure et capacité à continuer d’agir sous pression. La Volonté intervient dans le Neurodive, la Défense occulte et de nombreuses résistances mentales ou spirituelles.","charisme":"Présence, aisance relationnelle et capacité à influencer directement autrui. Le Charisme porte la négociation, l’autorité, la représentation, le commerce et les interactions fondées sur l’impact personnel."},"talent":{"sommeil_leger":"Même endormi, vous ne cessez jamais complètement de surveiller votre environnement.","resistance_a_la_chaleur":"Votre organisme et vos habitudes vous permettent de continuer à fonctionner lorsque la chaleur épuise les autres.","resistance_au_froid":"Le froid vous ralentit moins que la plupart des gens et vous savez préserver votre efficacité malgré l’exposition.","sante_de_fer":"Votre organisme résiste aux infections et récupère avec une régularité peu commune. Le repos vous remet plus vite sur pied, sans rendre votre corps invulnérable.","insensibilite_a_la_douleur":"La douleur vous informe sans commander tous vos gestes. Vous pouvez continuer là où la souffrance ferait céder quelqu’un d’autre, mais une blessure reste une blessure.","nageur":"Dans l’eau, vous êtes dans un élément familier plutôt que dans un environnement hostile.","ambidextre":"Vos deux mains savent travailler ensemble plutôt que se gêner. Avec deux armes adaptées, vous pouvez concentrer deux attaques sur une même ouverture, au prix d’une précision moindre.","brave":"La peur existe, mais elle vous pousse moins facilement à renoncer face à un danger concret.","fier_heritier":"Un patrimoine ou une rente familiale vous donne une aisance que votre seul métier n’expliquerait pas. Les plus favorisés peuvent ainsi accéder au Luxe.","renomme":"Votre nom circule au-delà des personnes qui vous connaissent directement. Ce que l’on raconte de vous ouvre des conversations et pèse dans les rapports de force, sans devenir une autorité universelle.","presence_remarquable":"Quelque chose chez vous attire immédiatement le regard : beauté, voix, allure, carrure, style ou autre trait impossible à ignorer.","apprentissage_fulgurant":"Vous transformez très vite une expérience réellement vécue en compétence exploitable et durable.","athlete":"Votre corps a été entraîné jusqu’à faire des efforts difficiles une pratique maîtrisée plutôt qu’une improvisation.","poings_de_fer":"Vous savez réellement frapper : placement, transfert de poids et impact rendent vos mains dangereuses sans arme.","stabilite_augmentique":"Votre identité et votre corps acceptent les transformations techniques avec une stabilité inhabituelle.","maitre_des_lames":"Une lame entre vos mains ne blesse pas au hasard. Une ouverture bien exploitée laisse une plaie que l’adversaire doit traiter plutôt que simplement ignorer.","resistance_aux_toxines":"Votre organisme encaisse drogues, poisons et substances agressives avec une résistance peu commune.","tireur_de_precision":"Vous avez assez répété l’acquisition d’une cible pour construire votre visée dans le geste de tir. Vous gagnez du temps sans transformer chaque balle en coup imparable.","pilote_emerite":"Vous sentez les réactions d’un véhicule assez tôt pour transformer contrôle et anticipation en avantage réel.","ombre_vivante":"Vous savez profiter d’une rupture de regard pour cesser presque immédiatement d’être une cible identifiable.","reflexes_defensifs":"Votre corps réagit même lorsque vous n’aviez pas anticipé l’attaque. Être pris de court ne suffit plus à vous priver de toute défense.","mains_lestes":"Vos doigts savent prendre, déplacer ou cacher un petit objet sans attirer l’attention sur le geste.","linguiste_emerite":"Vous entendez les parentés entre les langues et reconstruisez du sens là où d’autres n’entendent qu’un parler inconnu.","puits_de_savoir":"Une discipline est devenue un territoire familier. Vous y retrouvez vos connaissances et organisez la documentation avec l’efficacité d’un véritable spécialiste.","doc_de_choc":"Vous savez intervenir vite, proprement et utilement lorsque quelqu’un saigne et que le temps manque.","mecano_de_pointe":"Face à une machine ouverte, vous comprenez rapidement ce qui travaille, ce qui casse et ce qui peut être sauvé.","detective":"Vous avez le réflexe de chercher le détail qui ne colle pas et de relier les traces avant de tirer une conclusion.","stable":"Vous savez absorber le premier choc sans lui laisser immédiatement dicter votre conduite. Votre calme peut vaciller sans s’effondrer.","sens_accru_x":"L’un de vos sens a été affûté jusqu’à devenir une source d’informations que la plupart des gens ne remarquent même pas.","maitre_de_la_survie":"Vous pensez la survie à l’échelle du groupe. Repérage, collecte et organisation permettent aux compagnons de profiter réellement de votre expérience.","mental_dacier":"Pression, intimidation et usure psychologique trouvent chez vous une résistance volontairement entraînée.","neurodriver":"Le Holonet n’est pas seulement un outil que vous utilisez : vous avez développé les réflexes mentaux d’un véritable opérateur Neurodive.","seducteur_seductrice":"Vous savez reconnaître et employer les signes d’attirance sans confondre désir sincère, jeu social et intérêt calculé.","diplomate":"Vous écoutez ce qui bloque vraiment l’échange et cherchez ce que chaque partie pourrait encore accepter. Comprendre le compromis ne dispense pas de le construire.","maitre_du_troc":"Vous savez conserver une marge supplémentaire à l’achat comme à la vente. Votre maîtrise du commerce s’ajoute au résultat de la négociation plutôt que de simplement le décrire.","artiste":"Votre performance laisse une impression assez forte pour continuer à influencer ceux qui l’ont vue ou entendue.","autorite_naturelle":"Lorsque votre légitimité est reconnue, votre manière de donner une consigne pousse naturellement les autres à l’exécuter."},"sphereTalent":{"acces_fournisseur":"Vous traitez directement avec le circuit professionnel de votre corporation. Ses stocks, réservations et conditions d’achat vous évitent de dépendre du marché de détail.","assurance_corporative":"La corporation protège un actif dont dépend votre travail. Qu’il s’agisse d’un véhicule, d’un appareil ou d’une augmentation, sa destruction opérationnelle ne vous oblige pas à financer seul son remplacement.","avantages_salaries":"Votre contrat cumule deux avantages majeurs plutôt que d’imposer un choix entre eux. Cette sécurité matérielle reste liée à l’employeur qui la finance.","badge_interne":"Votre badge ouvre des portes que les salariés ordinaires ne connaissent parfois même pas. Cette confiance reste attachée à un programme précis, avec ses secrets et ses responsabilités.","compte_de_frais":"La corporation accepte de rembourser les dépenses professionnelles raisonnables engagées pour votre mission. Chaque paiement doit encore pouvoir être justifié comme frais de travail plutôt que comme dépense personnelle déguisée.","dotation_standard":"Votre employeur vous confie davantage que les outils indispensables. Cette dotation spécialisée est entretenue pour que vous puissiez accomplir un travail qui dépasse la routine du poste.","extraction_corporative":"Votre employeur a prévu de vous récupérer lorsque la mission tourne mal. La sécurité engage de vrais moyens, mais vous devez encore tenir et atteindre le point de rendez-vous.","profil_calibre":"Votre formation a été calibrée pour une fonction concrète. Dans votre spécialité professionnelle, vous savez reprendre une exécution qui vient de dérailler, sans disposer de secondes chances inépuisables.","programme_pilote":"Vous faites partie des personnes qui éprouvent un produit avant sa diffusion. Le prototype est un outil réel, doté d’une capacité écrite et suivi par une équipe qui attend vos retours de terrain.","requin_corporatif":"Vous maîtrisez les codes de négociation entre corporations : hiérarchies, langage contractuel, concessions et signaux de pouvoir. Dans ce milieu professionnel précis, Diplomatie ou Commerce bénéficie d’une expérience que le simple bagout ne remplace pas.","reseau_interne":"Vous connaissez personnellement quelqu’un dans un autre service de votre corporation. Ce Contact possède son vrai poste, ses propres intérêts et peut faire ce qu’un collègue de cette position serait réellement capable de faire.","service_juridique":"Le service juridique de votre employeur peut vous conseiller et vous représenter lorsque le problème relève réellement de votre travail. Il protège les intérêts de la corporation autant que les vôtres et ne devient pas votre cabinet privé universel.","assurance_silver":"Votre vie de Crawler inclut une véritable couverture CareForce Silver. Elle vous donne les prestations prévues par ce contrat. Le talent prend en charge son abonnement : la couverture est ajoutée automatiquement à vos services, sans charge mensuelle.","black_clinic":"Une clinique clandestine accepte de vous traiter sans vous faire entrer d’abord dans les cases d’une institution. La discrétion et le crédit d’urgence ne rendent pas la médecine gratuite.","contact_de_renom":"Votre réseau Crawler comprend une figure connue dans son milieu. Son nom peut ouvrir une conversation ou fournir une information difficile à atteindre, mais sa réputation ne fait pas de lui un serviteur disponible à volonté.","dans_le_coup":"Vous suivez la scène Neopunk de l’intérieur : lieux, collectifs, exclusions et nouvelles influences. Les pressions corporatives dont on parle dans les réseaux font aussi partie de cette actualité.","fixweb":"Vous appartenez au réseau oral des Fixers. Contrats, besoins et intermédiaires circulent par des personnes qui se connaissent de réputation, ce qui vous permet de chercher du travail ou un contact local sans transformer Fixweb en moteur de recherche omniscient.","logifake":"Vous possédez un profil Logifate de couverture préparé pour survivre aux contrôles ordinaires. Il raconte une identité numérique plausible avec assez de cohérence pour ne pas s’effondrer à la première vérification routinière.","maitrise_des_codes_de_la_rue":"Vous lisez les rapports de force actuels de la rue, pas seulement son vocabulaire. Vous savez qui approcher et quelles règles sont vraiment appliquées ici.","nid_de_frelons":"Les réseaux Neopunks vous reconnaissent comme quelqu’un qu’ils peuvent accueillir. Un lieu existant devient un repli concret avec des communications et des personnes attentives aux recherches visibles.","optitech":"Avec vos outils et un peu de préparation, vous savez régler un matériel familier au-delà de sa configuration standard. L’optimisation tient pour la scène et peut absorber une première défaillance matérielle ordinaire, sans rendre l’objet indestructible.","acces_aux_registres":"Une catégorie de dossiers confidentiels vous est réellement ouverte. Cette habilitation fournit des renseignements autrement inaccessibles, sans remplacer le travail d’enquête qui leur donne un sens.","appui_du_service":"Votre service affecte de vraies personnes à une tâche pendant que vous poursuivez l’opération. Leur compétence est connue et leur présence n’est pas une promesse abstraite.","autorite_officielle":"Vous êtes assermenté ou officiellement mandaté. Lorsqu’un ordre relève clairement de vos prérogatives, votre voix porte l’autorité de l’institution et pas seulement votre présence personnelle.","couverture_fonctionnelle":"L’institution considère certaines de vos initiatives comme des écarts qu’elle peut assumer. Sa protection a un effet réel sur les procédures qu’elle contrôle, pas sur la mémoire du monde entier.","dossier_institutionnel":"Votre couverture possède une existence officielle plutôt qu’un simple faux nom. Les services compétents la soutiennent et l’entretiennent pour vos opérations.","dotation_de_service":"Votre service vous laisse configurer une dotation spécialisée en fonction de la mission. Les outils nécessaires à tous les agents ne sont pas confondus avec ce complément personnel.","fonctionnaire_experimente":"Vous connaissez les recours et les responsables capables de débloquer un dossier. Un premier refus ne vous condamne pas à recommencer toute la démarche.","habilitation_administrative":"Vous êtes accrédité à des installations qui restent fermées aux agents ordinaires. Votre présence y est légitime même lorsque votre affectation quotidienne se trouve ailleurs.","priorite_interservices":"Vous pouvez faire converger deux services vers un même objectif local. La coopération change réellement le dispositif autour de votre intervention.","procedure_acceleree":"Vous savez obtenir une décision opérationnelle avant que le dossier ait fini de circuler. Les formalités suivent l’intervention au lieu de lui faire manquer sa fenêtre utile.","requisition_de_service":"Votre mission peut mobiliser un moyen matériel qui dépasse votre dotation personnelle. Il vous est réellement affecté, avec les responsabilités qu’implique son emploi.","reseau_administratif":"Vous avez conservé un Contact dans un autre service public. Cette personne donne une porte d’entrée humaine vers son administration, avec la compétence et les contraintes de son véritable poste.","armurier_du_milieu":"L’armurerie de votre organisation vous confie une arme adaptée à l’opération. Vous pouvez en changer au retour plutôt que financer un arsenal personnel pour chaque mission.","blanchiment":"Vous savez faire passer des revenus criminels par des activités et comptes capables de leur donner une origine légale crédible. Cela demande une filière réelle, du temps et des montants compatibles avec ce que la façade peut raisonnablement absorber.","corruption_locale":"Vous avez un Contact compromis dans une institution précise. Il peut détourner informations, procédures ou petits services à hauteur de son vrai poste, avec tous les risques personnels que cette corruption lui fait courir.","dette_de_faveur":"Quelqu’un s’est réellement engagé envers vous. Cette obligation porte sur un service significatif et peut se reconstituer par de nouveaux actes, pas par le simple passage du temps.","entreprise_de_couverture":"Vous possédez ou utilisez une activité légale capable de donner une façade à certaines opérations. Elle dispose d’une existence administrative, de locaux ou de flux plausibles, mais doit continuer à se comporter suffisamment comme une vraie entreprise pour tenir.","faussaires":"Votre organisation peut vous mettre en relation avec une filière qui fabrique de faux documents, papiers ou identités. Leur qualité dépend du travail commandé et aucun faux ne devient par principe indétectable à une vérification ciblée.","homme_femme_du_milieu":"Votre place dans le milieu est assez solide pour qu’on vous pardonne certains écarts. Cette indulgence ne vaut ni trahison impunie ni immunité auprès de la police.","marche_noir":"Vous avez accès à une filière qui fournit réellement les marchandises qu’elle distribue. Le prix et le transport restent des questions concrètes, mais trouver un vendeur n’est plus une aventure supplémentaire.","planque":"Votre organisation dispose d’un refuge concret auquel vous avez accès : appartement discret, arrière-boutique, garage ou autre lieu préparé. Il possède une adresse, des responsables et peut devenir compromis comme n’importe quelle planque réelle.","protection":"Votre organisation place un poids derrière votre nom. Là où sa protection est réellement redoutée, un adversaire moins influent doit réfléchir aux conséquences de s’en prendre à vous.","receleur":"Vous connaissez le circuit qui transforme objets volés ou illégaux en argent et inversement. Dans ce commerce particulier, votre réseau et votre habitude de négociation donnent un avantage que vous n’auriez pas sur un marché légal ordinaire.","autorite_religieuse":"Vous occupez une fonction que les fidèles de votre institution reconnaissent réellement. Dans ce cadre confessionnel, une consigne ou une médiation s’appuie sur l’autorité du ministère et de la communauté derrière vous.","communaute_de_fideles":"Les fidèles ont des voisins, des métiers et des conversations. Leur vie quotidienne fait remonter des observations et des rumeurs qu’aucun enquêteur isolé ne pourrait recueillir aussi facilement.","conseiller_spirituel":"Vous aidez quelqu’un à se préparer à l’épreuve qui l’attend. L’écoute et les repères construits ensemble peuvent lui donner une seconde chance lorsque le choc survient.","hebergement_religieux":"Vous disposez d’une base où revenir et laisser votre matériel. Cet espace réservé dépasse l’hospitalité d’une nuit, mais reste un lieu réel connu de l’institution.","ministere":"Votre fonction vous a donné connaissance d’activités que l’institution ne présente pas à tous ses fidèles. Vous pouvez connaître ses exorcistes et ses unités spécialisées tout en expliquant encore leurs affaires de manière profane.","mission_ecclesiastique":"Vous partez avec un mandat réel et les moyens de déplacement de la mission. Cette légitimité vous accompagne hors de votre affectation, sans effacer les règles des lieux où vous intervenez.","ordre_religieux":"Un spécialiste de votre Ordre entretient avec vous une relation de travail et de transmission. Il peut accomplir une expertise réelle, pas seulement vous renvoyer vers une autre adresse.","presence_holonet":"Votre institution vous a donné une place visible dans ses canaux Holonet officiels. Vous savez y rechercher ou y prendre la parole avec la crédibilité d’un acteur reconnu de ce réseau médiatique confessionnel.","reseau_caritatif":"Le réseau engage une véritable opération d’assistance. Il peut prendre en charge des personnes que vous devez protéger ou vous intégrer à une activité humanitaire qui ouvre un terrain d’intervention.","reseau_confessionnel":"Vous arrivez avec un garant plutôt qu’en parfait inconnu. Le réseau confessionnel peut vous présenter aux personnes que son implantation locale connaît réellement.","soutien_communautaire":"Votre communauté sait se mobiliser pour des besoins profanes modestes : repas, bénévoles, transport, traduction, collecte ou présence. Vous organisez cette entraide humaine rapidement sans lui inventer des compétences professionnelles qu’elle ne possède pas.","education_theologique":"Vous savez confronter une autorité aux principes qu’elle prétend représenter. Une contradiction exposée devant ses fidèles peut ébranler son ascendant sans changer magiquement leurs convictions.","omerta":"Le silence est une pratique collective autant qu’une résistance personnelle. Vos associés savent ce qu’ils ne doivent pas raconter et vous préviennent lorsqu’on cherche à en apprendre davantage.","fiable":"Votre réputation de professionnel sérieux peut être vérifiée. Un commanditaire peut vous confier une avance parce que votre engagement a déjà fait ses preuves.","bonnes_adresses":"Ce Talent représente un avantage concret acquis par votre place dans Crawler : il existe dans la fiction avant d’exister dans les chiffres.","insignifiant":"Ce Talent représente un avantage concret acquis par votre place dans Crawler : il existe dans la fiction avant d’exister dans les chiffres."}},"choices":{"formation_publique":{"kind":"skill","label":"Compétence d’Esprit choisie","skillAttribute":"esprit","bonus":1,"permanent":true,"help":"Ce choix applique réellement +1 à la Compétence choisie."},"formation_calibree":{"kind":"skill","label":"Compétence d’Esprit choisie","skillAttribute":"esprit","bonus":1,"permanent":true,"help":"Ce choix applique réellement +1 à la Compétence choisie."},"petites_combines":{"kind":"skill","label":"Compétence choisie","skills":["commerce","larcin"],"bonus":2,"contextual":true,"help":"Le bonus reste circonstanciel et n’augmente pas la valeur permanente de la Compétence."},"education_caritative":{"kind":"skill","label":"Compétence choisie","skills":["soin","diplomatie","savoirs"],"bonus":2,"contextual":true,"help":"Le bonus reste circonstanciel et n’augmente pas la valeur permanente de la Compétence."},"culture_produit":{"kind":"text","label":"Secteur corporatif maîtrisé","placeholder":"Ex. armement, biotech, transport, médias…","contextual":true,"help":"Ce choix précise le secteur auquel s’applique le Talent."},"requin_corporatif":{"kind":"skill","label":"Compétence choisie","skills":["diplomatie","commerce"],"bonus":2,"contextual":true,"help":"Choix effectué à l’acquisition ; le +2 s’applique dans les négociations professionnelles entre corporations."},"homme_femme_du_milieu":{"kind":"skill","label":"Compétence choisie","skills":["diplomatie","autorite"],"bonus":1,"contextual":true,"help":"Choix effectué à l’acquisition ; le +1 s’applique dans les interactions internes à votre organisation."},"presence_remarquable":{"kind":"text","label":"Trait remarquable","placeholder":"Ex. beauté, voix, allure, style, carrure…","contextual":true,"help":"Le +2 ne s’applique que lorsque ce trait précis constitue réellement un avantage."},"puits_de_savoir":{"kind":"text","label":"Grand domaine de connaissance","placeholder":"Ex. droit corporatif, biotech, occultisme comparé…","contextual":true,"help":"Ce domaine est celui dans lequel le Talent ouvre les recherches spécialisées."},"sens_accru_x":{"kind":"enum","label":"Sens accru","options":[{"id":"vue","name":"Vue"},{"id":"ouie","name":"Ouïe"},{"id":"odorat","name":"Odorat"},{"id":"toucher","name":"Toucher"},{"id":"gout","name":"Goût"}],"bonus":2,"contextual":true,"help":"Le +2 Perception s’applique lorsque ce sens précis est déterminant."},"badge_interne":{"kind":"text","label":"Programme ou branche confidentielle","placeholder":"Périmètre de sites sécurisés et secrets","help":"L’accès physique est réel dans ce périmètre ; il ne donne aucun droit MJ sur le site."},"profil_calibre":{"kind":"skill","styleSkills":true,"permanent":false,"bonus":0,"label":"Compétence professionnelle du Style","help":"Une relance par scénario, hors échec narratif. Aucun bonus permanent. Un ancien choix libre est conservé et doit être vérifié."},"programme_pilote":{"kind":"text","label":"Prototype et fonction expérimentale","placeholder":"Modèle, amélioration unique, limites et programme d’essai","help":"Définir la fiche complète avec le MJ avant l’achat du talent. Un seul prototype prêté à la fois ; aucun pouvoir de Vérité automatique."},"habilitation_administrative":{"kind":"text","label":"Secteur gouvernemental secret","placeholder":"Ex. installations de renseignement ou dépôts sécurisés","help":"Accréditation physique des sites de ce secteur ; les données confidentielles relèvent d’Accès aux registres."},"acces_aux_registres":{"kind":"text","label":"Catégorie de données confidentielles","placeholder":"Police et enquêtes, dossiers médicaux, Logifate…","help":"Choisir une grande catégorie cohérente. L’habilitation ouvre les données, mais ne remplace pas les tests d’interprétation."},"dossier_institutionnel":{"kind":"text","label":"Identité opérationnelle de couverture","placeholder":"Nom, profession de couverture et service répondant","help":"Une couverture officielle active, remplaçable entre deux opérations. Elle ne modifie ni le visage ni les traces déjà découvertes."},"ministere":{"kind":"text","label":"Domaine confidentiel religieux et canal connu","placeholder":"Exorcistes, protection de reliques, dossiers d’incidents…","help":"Connaissances institutionnelles et explications profanes. Aucun passage automatique de Profane à Initié."},"ordre_religieux":{"kind":"text","label":"Discipline et correspondant de l’Ordre","placeholder":"Nom ou fonction du spécialiste, discipline et moyens","help":"Une expertise réelle par scénario ; les apprentissages restent payés avec leurs XP normaux."}},"skillMap":{"athlete":"athletisme","poings_de_fer":"pugilat","stabilite_augmentique":"humanite","tireur_de_precision":"tir","pilote_emerite":"pilotage","ombre_vivante":"furtivite","reflexes_defensifs":"esquive","mains_lestes":"larcin","linguiste_emerite":"langages_argot","puits_de_savoir":"savoirs","doc_de_choc":"soin","mecano_de_pointe":"mecanique","detective":"investigation","maitre_de_la_survie":"survie","mental_dacier":"force_mentale","neurodriver":"neurodive","seducteur_seductrice":"seduction","diplomate":"diplomatie","maitre_du_troc":"commerce","artiste":"representation","autorite_naturelle":"autorite","discipline_de_foi":"maitrise_spirituelle"}}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'creation', 'desavantages_aides', 'Textes d''aide des désavantages', NULL, '{"nature":"creation","lore":{"sensible_a_la_chaleur":"Votre organisme supporte mal les températures élevées : chaleur sèche, humidité lourde et déshydratation vous épuisent plus vite que la plupart des gens.","sensible_au_froid":"Le froid mord rapidement jusqu’aux os ; votre corps perd plus vite son efficacité lorsque la température chute.","miserable_endette":"Votre situation quotidienne est déjà mangée par une dette, un créancier ou des charges qui ne vous laissent jamais vraiment respirer financièrement.","guerison_lente":"Les blessures se referment chez vous avec une lenteur frustrante ; chaque coup sérieux laisse une trace plus longtemps que prévu.","scrupuleux":"Vous possédez une limite morale que vous prenez réellement au sérieux ; la franchir n’est jamais un simple choix tactique oublié à la scène suivante.","impulsif":"L’action vous attire avant que toutes les conséquences soient pesées ; face à l’occasion immédiate, réfléchir devient parfois l’effort le plus difficile.","violent":"L’humiliation ou la menace réveillent chez vous une réponse agressive difficile à contenir ; partir ou frapper peut sembler plus naturel que laisser couler.","obsede":"Une idée, une personne, une quête ou un besoin occupe trop de place dans votre esprit pour rester toujours raisonnable.","hypocrite":"Vous défendez publiquement une image ou une valeur que vos propres actes ne respectent pas toujours ; le vrai danger commence lorsque quelqu’un peut le prouver.","dependance":"Une substance, une pratique ou un comportement a pris une place dont votre équilibre dépend désormais réellement.","unsinkable":"Votre système nerveux refuse ou ne supporte pas l’interface Neuro : dans un monde saturé de guidage et de Neuroprogrammes, vous restez définitivement à l’extérieur de cette couche technologique.","integrite_defaillante":"L’augmentique et les agressions de l’esprit trouvent chez vous un équilibre intérieur déjà fragile ; votre sentiment d’intégrité se fissure plus facilement.","inconnu":"Vous n’avez pas encore de nom qui ouvre des portes : personne ne vous attend, personne ne vous recommande, et votre réputation reste à construire entièrement.","lent_a_reagir":"Il vous faut un instant de plus pour passer de la compréhension à l’action ; dans une situation brutale, cet instant peut compter.","traumatise":"Une expérience passée a laissé un déclencheur précis capable de ramener immédiatement une partie de la peur, de la douleur ou de l’impuissance vécue.","frele":"Faiblesse de Vigueur : votre corps manque de puissance brute et les charges lourdes deviennent rapidement un problème concret.","maladif":"Faiblesse de Vigueur : infections, maladies et complications physiologiques vous atteignent plus facilement que la moyenne.","neurocompatibilite_nulle":"Faiblesse de Vigueur : votre organisme tolère particulièrement mal le Stress augmentique dès que les implants cessent d’être purement neutres.","malhabile":"Faiblesse d’Agilité : vos gestes fins manquent de précision lorsque rapidité et dextérité doivent fonctionner ensemble.","pataud":"Faiblesse d’Agilité : votre corps trahit plus facilement votre présence par le mouvement, le bruit ou une mauvaise gestion de l’espace.","mauvais_tireur":"Faiblesse d’Agilité : toucher reste possible, mais placer exactement le tir là où vous le souhaitez vous demande davantage de marge.","obtus":"Faiblesse d’Esprit : les idées entièrement nouvelles mettent du temps à trouver leur place, surtout lorsqu’aucune expérience concrète ne vous permet de les raccrocher à quelque chose de connu.","traumatisme_22":"Faiblesse d’Esprit : le Bond technologique a laissé une partie de vos réflexes culturels derrière lui et certaines évidences de 2035 ne le sont toujours pas pour vous.","mauvais_fouilleur":"Faiblesse d’Esprit : vous pouvez comprendre une enquête sans être celui qui remarque la petite trace physique cachée au mauvais endroit.","lache":"Faiblesse de Volonté : lorsque le danger devient physique, immédiat et clairement mortel, votre instinct cherche d’abord une sortie.","sensible_au_stress":"Faiblesse de Volonté : sous une pression psychologique brutale, votre équilibre peut basculer beaucoup plus vite que vous ne le voudriez.","esprit_ouvert":"Faiblesse de Volonté : votre esprit est plus perméable aux intrusions et aux manipulations directes qui cherchent à entrer plutôt qu’à convaincre.","presence_rebutante":"Faiblesse de Charisme : quelque chose dans votre apparence, votre attitude ou votre réputation provoque un recul immédiat lorsqu’une relation de séduction est en jeu.","mal_a_laise":"Faiblesse de Charisme : face à des inconnus et aux codes sociaux formels, créer rapidement une relation fluide vous demande un effort réel.","voix_ingrate":"Faiblesse de Charisme : votre voix dessert les situations où cadence, timbre et présence vocale comptent autant que les mots.","corporatiste:contrat_leonin":"La corporation ne vous emploie pas seulement : elle possède sur vous une dette, un contrat ou un investissement assez important pour peser sur vos décisions.","corporatiste:sous_surveillance":"Quelqu’un dans la hiérarchie a décidé que votre activité méritait un regard particulier ; utiliser les ressources de l’entreprise laisse donc plus de traces que vous ne le souhaiteriez.","corporatiste:placardise":"Votre dossier interne vous suit d’étage en étage : on vous confie encore ce qu’on doit vous confier, rarement ce qui pourrait réellement vous faire progresser.","corporatiste:rival_interne":"Un autre employé transforme votre carrière en partie à somme nulle et dispose de raisons très concrètes de souhaiter votre échec.","corporatiste:profil_sous_condition":"Votre Logifate vous maintient tout juste dans la bonne case ; la prochaine mauvaise évaluation peut suffire à faire basculer votre statut.","crawler:mauvaise_reputation":"Dans l’Underlife, les histoires voyagent plus vite que les dossiers officiels : un contrat raté ou une trahison supposée suffit à fermer des portes avant même votre arrivée.","crawler:traque":"Quelqu’un vous cherche réellement, avec assez de moyens ou de motivation pour que changer de quartier ne règle pas le problème.","crawler:anomaly_under_system":"Les systèmes qui classent les citoyens vous considèrent comme une anomalie, un Hors Système ou un risque ; parfois, la machine vous repère avant l’humain.","crawler:grille_sur_le_fixweb":"Votre pseudo circule avec les mauvais commentaires : quand un fixer voit votre nom, il commence par se demander ce qui va mal tourner.","crawler:dette_de_la_blanchisserie":"La Blanchisserie — ou un réseau équivalent — vous a déjà rendu un service dont le prix n’est pas encore soldé.","gouvernementale:dossier_disciplinaire":"Votre administration possède déjà une version écrite de vos erreurs ; chaque demande de confiance supplémentaire peut rouvrir ce dossier.","gouvernementale:sous_enquete_interne":"Inspection, hiérarchie ou agence vous observe de plus près que vos collègues et attend peut-être simplement l’élément qui confirmera ses soupçons.","gouvernementale:habilitation_restreinte":"Votre fonction promet plus d’accès que votre badge n’en autorise réellement ; certains dossiers restent derrière une porte que votre poste devrait pourtant ouvrir.","gouvernementale:devoir_de_reserve":"Votre vie publique engage l’institution : une opinion, une vidéo ou un scandale privé peut devenir une faute professionnelle.","gouvernementale:ennemi_administratif":"Votre adversaire n’a pas besoin d’envoyer des tueurs ; formulaires, contrôles, décisions et procédures suffisent à rendre votre vie beaucoup plus compliquée.","mafieuse:dette_envers_la_famille":"La Famille vous a avancé argent, protection ou service, et dans ce milieu une dette n’est jamais seulement une ligne comptable.","mafieuse:dette_de_sang":"Quelqu’un n’attend plus une compensation financière mais une réparation personnelle pour ce que vous avez fait à l’un des siens.","mafieuse:marque_du_milieu":"Votre appartenance se lit sur vous pour qui connaît les signes : tatouage, augmentation, accent, cicatrice ou manière de vous présenter raconte déjà une histoire criminelle.","mafieuse:rival_interne":"Un autre membre de l’organisation veut votre place, vos affaires ou vos contacts et connaît suffisamment le milieu pour vous frapper sans sortir de ses règles.","mafieuse:sous_surveillance_policiere":"Votre nom existe déjà dans un dossier actif ; la prochaine erreur ne commencera donc pas par une enquête, mais par des gens qui savent déjà où regarder.","religieuse:scandale":"Une affaire embarrassante s’est attachée à votre nom et affaiblit chaque fois que vous prétendez incarner une autorité morale ou institutionnelle.","religieuse:heterodoxe":"Votre foi ou votre doctrine diverge assez de la ligne officielle pour que certains supérieurs se demandent si vous êtes encore des leurs.","religieuse:devoir_pastoral":"Des personnes comptent réellement sur vous : partir en mission ou poursuivre vos propres objectifs signifie parfois laisser derrière vous une communauté vulnérable.","religieuse:sous_surveillance_ecclesiastique":"Un supérieur ou un conseil religieux doute de votre orthodoxie, de vos méthodes ou de votre fiabilité et garde désormais un œil sur vos actes.","religieuse:vu_interdit":"Vous avez choisi une règle de vie assez importante pour que la violer soit une rupture intérieure, pas un simple détail de comportement."}}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
